  AvgDialog_118957_Content_14 = {
    Text = "例えば…………ミサゴですか？"
  },
  AvgDialog_118957_Content_15 = {
    Text = "ミサゴの人たちは、みんなの変わった癖を受け入れる…………あるいは丸くするのがとても上手みたいです。"
  },
  AvgDialog_118957_Content_16 = {
    Text = "ある年、マーフィーがあらゆる味のキャンディを全部食べたいと駄々をこねて、結局歯が痛くなったことがありました。"
  },
  AvgDialog_118957_Content_17 = {
