  AvgDialog_120291_Content_10 = {
    Text = "ほんのりピンク色で喉に詰まりそうな、明らかに上等とは言えない菓子が口に押し込まれた。生地がわずかにほどけた途端、唾液が口の中で狂ったように分泌し始めた。"
  },
  AvgDialog_120291_Content_11 = {
