  AvgDialog_130451_Content_17 = {
    Text = "オジール？私の声が聞こえる？"
  },
  AvgDialog_130451_Content_18 = {
    Text = "あなたを縛る力がかすかに震えたかと思うと、すぐにまた締め付けられた。まるで二つの意志の間で何度も引き裂かれているかのようだった。"
  },
  AvgDialog_130451_Content_19 = {
    Text = "私の無力さのせいで、やはりあなたを傷つけてしまった。もっと良い方法であなたを守ることができれば……"
  },
  AvgDialog_130451_Content_2 = {
    Text = "今回の任務は難しくはなかった。経験豊富なシークレットキーパーとして、あなたと負誓·オジールは難なく全ての敵を片付けた。しかし、一瞬の油断から、手首に小さな傷跡を残してしまった。"
  },
  AvgDialog_130451_Content_20 = {
    Text = "あなたにはわずかな言葉しか聞こえなかった。まるで独り言のようだった。"
