  AvgDialog_139659_Content_8 = {
    Text = "晴れたみたいだ。"
  },
  AvgDialog_139659_Content_9 = {
    Text = "外を確認しよう。"
  },
  AvgDialog_139660_Content_1 = {
    Text = "「記憶」"
  },
  AvgDialog_139660_Content_10 = {
    Text = "私は君の言う通り、普通ではないかな。\nミサゴ大学っていう場所の調査員だよ。"
  },
  AvgDialog_139660_Content_11 = {
    Text = "沙耶の瞳に戸惑いが浮かぶ。\nそれらの言葉は、彼女にはあまり馴染みがないようだ。"
  },
  AvgDialog_139660_Content_12 = {
    Text = "説明すると長くなる……\n今はもっと優先すべきこともあるしね。"
  },
  AvgDialog_139660_Content_13 = {
    Text = "私のパートナーのラモンナが……\n何かに呑み込まれるのを見たんだ。あれは……"
  },
  AvgDialog_139660_Content_14 = {
    Text = "言葉はそこで途切れた。\n続けることができない。"
  },
  AvgDialog_139660_Content_15 = {
    Text = "あの瞬間に脊髄の奥から這い上がってきた恐怖を伝えるには、言葉だけでは、あまりにも空虚だった。"
  },
  AvgDialog_139660_Content_16 = {
    Text = "ラモンナを永遠に失うかもしれないという恐怖。"
  },
  AvgDialog_139660_Content_17 = {
    Text = "彼女は、私にとってかけがえのない人だから。"
