  AvgDialog_139660_Content_18 = {
    Text = "沙耶の視線が一瞬、焦点を失う。"
  },
  AvgDialog_139660_Content_19 = {
    Text = "かけがえのない人……そうなんだ。"
  },
  AvgDialog_139660_Content_2 = {
    Text = "疑問が胸の中で渦巻くまま、整理もつかないうちに、少女が先に口を開いた。"
  },
  AvgDialog_139660_Content_20 = {
    Text = "わたしにもいた……ような気がする。"
  },
  AvgDialog_139660_Content_21 = {
    Text = "彼女は俯き、眉を寄せて呟く。"
  },
  AvgDialog_139660_Content_22 = {
    Text = "誰か、とても大切な人。\nその人の顔を……覚えているはずなのに。\n絶対に覚えているのに。\nでも、思い出そうとすると――"
  },
  AvgDialog_139660_Content_23 = {
    Text = "――輪郭しか見えないの。\n曇りガラスを見てるみたいに。\nそこにいるってわかるし、大切だってわかるのに。\n細かいところは全部……見えなくなってる。"
  },
  AvgDialog_139660_Content_24 = {
    Text = "その人だけじゃなくて……ほかも全部。\nやらなきゃいけないことがあるって、わかってる――\nすごく大切なことが。"
  },
  AvgDialog_139660_Content_25 = {
    Text = "でも記憶になにか混ざり合ってるみたいで。\nひとつの記憶ではその人のことを優しいって言ってる。\n別の記憶だとわたしは暗い場所にずっといたんだって言ってる。"
  },
  AvgDialog_139660_Content_26 = {
    Text = "ある記憶だとわたしは誰かが迎えに来るのを待ってるの。\nでも、また別の記憶だと……わたしは誰かを怖がらせるようなことをしなきゃいけないって言ってる。"
  },
  AvgDialog_139660_Content_27 = {
    Text = "全部が本当にあったことみたいに感じる。\nでも……全部並べてみると、なぜかつじつまが合わないの。"
  },
  AvgDialog_139660_Content_28 = {
    Text = "あなたはこの症状を知っている。"
  },
  AvgDialog_139660_Content_29 = {
    Text = "彼女にだけ起こる状況ではない――融蝕現象の報告書で見た症状だ。\n意識の混濁、記憶の断片化、自己認識の崩壊。"
  },
  AvgDialog_139660_Content_3 = {
    Text = "わたしは……えーと、『沙耶』、かな。\nところでさ、あなたは、ここがどこかわかる？"
  },
  AvgDialog_139660_Content_30 = {
    Text = "どれが本当のことか、わからないの。\n本当の記憶が……わからない。"
  },
  AvgDialog_139660_Content_31 = {
    Text = "沙耶の指がぎゅっと握られる。\n存在しない何かを掴もうとしているように。"
  },
  AvgDialog_139660_Content_32 = {
    Text = "その揺らぎに呼応するように、周囲の景色が変質し始めた。"
  },
  AvgDialog_139660_Content_33 = {
    Text = "危ない！"
  },
  AvgDialog_139660_Content_34 = {
    Text = "あなたはタンポポの花畑と、その境界を見る。\n黒い液体に覆われた肉の膜が、じわじわと迫ってきている。\n花畑の境界は今にも崩れそうだった。"
  },
  AvgDialog_139660_Content_4 = {
    Text = "なんでこんなところにいるんだろ……\nうーん、なんか色々と思い出せないなぁ。"
  },
  AvgDialog_139660_Content_5 = {
    Text = "……あなた、普通の人じゃなさそう？\n何か特別な力を持ってる……？"
  },
  AvgDialog_139660_Content_6 = {
    Text = "あなたはすぐには答えなかった。沙耶と名乗る少女は手を離し、少し下がってから目を細めて、あなたを観察する。"
  },
  AvgDialog_139660_Content_7 = {
    Text = "わたしを見て、何も感じない？\nあなたはどうしてここに来たの？"
  },
  AvgDialog_139660_Content_8 = {
    Text = "ちょ、ちょっと待って。\nひとつずつ聞いて。"
  },
  AvgDialog_139660_Content_9 = {
    Text = "おそらくだけど……\n私の経験上だと、ここは『密境』と呼ばれるところだと思う。"
  },
  AvgDialog_139661_Content_1 = {
    Text = "心象風景"
  },
  AvgDialog_139661_Content_10 = {
    Text = "美しい少女と、一人の青年。"
  },
  AvgDialog_139661_Content_11 = {
    Text = "二人は手を取り合い、親しげに、砂と風の吹き荒ぶ荒野を歩いている。"
  },
  AvgDialog_139661_Content_13 = {
    Text = "彼女は笑いながら、両手を広げて風を抱きしめる。"
  },
  AvgDialog_139661_Content_14 = {
    Text = "隣の青年も身を寄せ、彼女の軽やかな笑い声に耳を傾ける。"
  },
  AvgDialog_139661_Content_15 = {
    Text = "空は晴れているのに、どこか寂しさを帯びている。"
  },
  AvgDialog_139661_Content_16 = {
    Text = "それでも、寄り添う二人の姿からは、胸の奥から湧き上がるような幸福が感じられた。"
  },
  AvgDialog_139661_Content_17 = {
    Text = "たとえ周囲に誰もいなくても、\n誰にも理解されず、祝福されなくても――\nその愛は、確かにそこにあった。"
  },
  AvgDialog_139661_Content_18 = {
    Text = "そして、夢は唐突に途切れる。\n砂嵐がすべてをさらっていった。"
  },
  AvgDialog_139661_Content_19 = {
    Text = "世界は、虚無の闇へと落ちていく。"
  },
  AvgDialog_139661_Content_2 = {
    Text = "天地は、すべて砂でできていた。"
  },
  AvgDialog_139661_Content_20 = {
    Text = "――そのとき、一人の歌姫が、星々を旅してたの。"
  },
  AvgDialog_139661_Content_21 = {
    Text = "荒れ果てた宇宙の中で、彼女はひとつのシルバーコアを拾い上げてね。"
  },
  AvgDialog_139661_Content_22 = {
    Text = "それに触れた瞬間、『わたし』は目を覚ましたの。"
  },
  AvgDialog_139661_Content_23 = {
    Text = "『わたし』は記憶を失っていて、自分は『かけがえのない人』を探さなきゃいけないということだけを知っていた。"
  },
  AvgDialog_139661_Content_24 = {
