  AvgDialog_18797_Content_16 = {Text = "え？"},
  AvgDialog_18797_Content_17 = {
    Text = "あの洪水が来るずっと前に、余は神の夢から未来を覗く力を失った。余は彼の神格の行方を知らない。彼の神格は目覚めたのかもしれないし、去ったのかもしれない。"
  },
  AvgDialog_18797_Content_18 = {
    Text = "じゃあ、あなたの予言は……"
  },
  AvgDialog_18797_Content_19 = {
