  },
  AvgDialog_18798_Content_10 = {
    Text = "マーフィーは力を抜き、船舷に背を預けて甲板に滑り落ち、淑女としての座り方を気にする余裕もなかった。"
  },
  AvgDialog_18798_Content_11 = {
    Text = "彼女は倒れないように支えを探し、探し回った末にあなたの肩に寄りかかった。"
