  AvgDialog_18935_Content_20 = {
    Text = "貧しさや苦難の痕跡を探そうと彼女の体の隅々まで見回したが、徒労に終わった。"
  },
  AvgDialog_18935_Content_21 = {
    Text = "お前はおしゃべりがあまり好きではないようだな。安心したまえ、今のところお前を蝋人形にするつもりはないから……自由に話していいぞ。"
  },
  AvgDialog_18935_Content_22 = {
