  AvgDialog_18947_Content_6 = {
    Text = "放っておこう。倒せないなら逃げるまでだ。\nあたしの得意技だからな！"
  },
  AvgDialog_18947_Content_7 = {
    Text = "ブラウン、ついてこい、一気に突き抜けるぞ！"
  },
  AvgDialog_18947_Content_8 = {
    Text = "チューッ！（はい、ただ今！）"
  },
  AvgDialog_18948_Content_1 = {
    Text = "あああ——！！"
  },
  AvgDialog_18948_Content_10 = {
    Text = "私は、誰……？"
  },
  AvgDialog_18948_Content_11 = {
    Text = "そうよ……私は一体誰なのかしら。"
  },
  AvgDialog_18948_Content_12 = {
    Text = "名前なんて、もう覚えていない……"
  },
  AvgDialog_18948_Content_13 = {
    Text = "これは君のために新しく作ってあげた顔だよ。\n気に入ったかな？"
  },
  AvgDialog_18948_Content_14 = {
    Text = "これは……誰？鏡に映っている怪物は、誰なの？"
  },
  AvgDialog_18948_Content_15 = {
    Text = "君が誰で、鏡の中の人が誰なのか、そんなことはどうでもいい。"
  },
  AvgDialog_18948_Content_16 = {
    Text = "過去を忘れろ。\nそんなものは何の役にも立たない。"
  },
  AvgDialog_18948_Content_17 = {
    Text = "自分の実験番号をしかと覚えておきたまえ、<Blue:24>——それが君の余生と共にあるのだ。"
  },
  AvgDialog_18948_Content_18 = {
    Text = "<Shake:私の人生は……終わった、台無しにされた……>"
  },
  AvgDialog_18948_Content_19 = {
    Text = "もし君の悲惨で無意味な生活を「人生」と呼ぶのなら……"
  },
  AvgDialog_18948_Content_2 = {
    Text = "女の人は自分の首をきつく絞めている。顔の筋肉がピクピクと痙攣し、目玉が今にも飛び出しそうな勢いで回っている。"
  },
  AvgDialog_18948_Content_20 = {
    Text = "そうだな、それは確かに遠く去っていった。"
  },
  AvgDialog_18948_Content_21 = {
    Text = "ちがう、ちがう……呪ってやる！"
  },
  AvgDialog_18948_Content_22 = {
    Text = "<Red:みんな呪ってやる、><RedBig:地獄に落ちるがいいわ！>"
  },
  AvgDialog_18948_Content_24 = {
    Text = "24……思い出した。"
  },
  AvgDialog_18948_Content_25 = {
    Text = "はじめまして、私のことは24と呼んで。"
  },
  AvgDialog_18948_Content_26 = {
    Text = "24？変てこな名前だな、なんだそれ？"
  },
  AvgDialog_18948_Content_27 = {
    Text = "24は壁の隅に縮こまって懸命に首を振るだけで、もうひと言も話そうとしない。"
  },
  AvgDialog_18948_Content_29 = {
    Text = "自分の過去についてあまり話したくないみたいね。\nじゃあ蝋人形館のことなら？話してくれるかしら？"
  },
  AvgDialog_18948_Content_3 = {
    Text = "精神が不安定で制御できていないみたい……%player%、シルバーキーで落ち着かせて！"
  },
  AvgDialog_18948_Content_30 = {
    Text = "例えば「三つの規則」について……"
  },
  AvgDialog_18948_Content_31 = {
    Text = "<Big:シーッ！！>"
  },
  AvgDialog_18948_Content_32 = {
    Text = "大きな声で言わないで。<Blue:「あいつら」>に聞こえるわ。"
  },
  AvgDialog_18948_Content_33 = {
    Text = "「あいつら」って？"
  },
  AvgDialog_18948_Content_34 = {
    Text = "24は警戒しながら左右を見回し、あなたたちに近づくと、再び恐ろしげな口調になった。"
  },
  AvgDialog_18948_Content_35 = {
    Text = "<Shake:あいつらは、あいつらよ……>"
  },
  AvgDialog_18948_Content_36 = {
