  },
  AvgDialog_18959_Content_47 = {
    Text = "あいつら二人は好き勝手にやりすぎた。慎み深さとはどういうことか知ってもらうために、少しお灸を据えてやろう。"
  },
  AvgDialog_18959_Content_48 = {
    Text = "帰り際にパンディアがお前への謝罪だと言って、こんなものを渡してきたよ。"
  },
  AvgDialog_18959_Content_49 = {
    Text = "何だこれは……プロフィール？"
  },
  AvgDialog_18959_Content_5 = {
    Text = "あそこはすっかり融蝕に侵されていて、シルバーコアのかけらさえ見つかりませんでした。"
  },
  AvgDialog_18959_Content_50 = {
    Text = "開けてみろよ、びっくりするぜ。"
  },
  AvgDialog_18959_Content_52 = {
    Text = "生年月日は不明……昨年ミサゴ大学に登録されたばかりで、訓練を受けたことがないのに複数の覚醒体とリンクして戦える……"
  },
  AvgDialog_18959_Content_53 = {
    Text = "実に面白いやつだ。\nミサゴ大学がこんな手を隠していたとは。"
  },
  AvgDialog_18959_Content_54 = {
    Text = "どうやらあの年の「提灯事件」では十分に教訓を与えられなかったようだな。"
  },
  AvgDialog_18959_Content_55 = {
    Text = "大学に戻って、親愛なるわが師の墓参りをするときが来たか。"
  },
  AvgDialog_18959_Content_56 = {
    Text = "ロンディニウム郊外\nショーディッチ墓地"
  },
  AvgDialog_18959_Content_57 = {
    Text = "24さん。"
  },
  AvgDialog_18959_Content_58 = {
    Text = "%player%{Male=さん,Female=さん}！どうしてここに……"
  },
  AvgDialog_18959_Content_59 = {
    Text = "ジェンキンに会いに来た。"
  },
  AvgDialog_18959_Content_6 = {
    Text = "死後にシルバーコアを析出する人はごくわずかですから。\nこのことはとうに知っているはずでしょう。"
  },
  AvgDialog_18959_Content_60 = {
    Text = "あなたはしゃがんで、小さな墓碑の上の埃をそっと払った。墓碑には何も刻まれていない。\nあなたたちがまだそこに文字を刻む心の準備ができていないからだ。"
  },
  AvgDialog_18959_Content_61 = {
    Text = "ひとたび文字が刻まれると、ジェンキンの死が現実になってしまうかのようで。"
  },
  AvgDialog_18959_Content_62 = {
    Text = "24さん、蝋人形館にいたとき、どうしてあなたの正体を教えてくれなかったの？"
  },
  AvgDialog_18959_Content_64 = {
    Text = "あのときは頭が混乱していて、怖くて……ジェンキンが私のこの姿を見たら、きっと悲しむだろうと思って。"
  },
  AvgDialog_18959_Content_65 = {
    Text = "ジェンキンは並みの子供じゃない。\n彼女なら耐えられたよ。"
  },
  AvgDialog_18959_Content_66 = {
    Text = "そうね……私の知る限り、一番勇敢で強い子だった。"
  },
  AvgDialog_18959_Content_67 = {
    Text = "大学のことはみんな聞いたわ。\nジェンキンのシルバーコアはまだ見つかっていないのね？"
  },
  AvgDialog_18959_Content_68 = {
    Text = "ウィリアム先輩のほうにはまだ新しい情報がない。\nでも安心して、24さん。"
  },
  AvgDialog_18959_Content_69 = {
    Text = "ロジャーズが捕まったら、私が直接尋問するから。"
  },
  AvgDialog_18959_Content_7 = {
    Text = "でも彼女は、ジェンキンは、違うんです……"
  },
  AvgDialog_18959_Content_70 = {
    Text = "24は首を横に振った。"
  },
  AvgDialog_18959_Content_71 = {
    Text = "あなたが諦めないことは分かっているわ。\nただ心配なの……ジェンキンの記憶がもう薄れてきていて。"
  },
  AvgDialog_18959_Content_72 = {
    Text = "あの子が本当に私の前に立つ日が来ても、見分けられないんじゃないかと心配で。"
  },
  AvgDialog_18959_Content_73 = {
    Text = "それなら忘れたときに、教えてあげる。"
  },
  AvgDialog_18959_Content_74 = {
    Text = "二人がどうやって出会い、暮らしてきたのか。彼女がどうやってあなたを救ったのか。\nそしてどうやって私たちの救世主になったのか……"
  },
  AvgDialog_18959_Content_75 = {
    Text = "声は徐々に小さくなり、最後にはそよ風に吹かれて消えた。"
  },
  AvgDialog_18959_Content_76 = {
    Text = "チュー……チュー……"
  },
  AvgDialog_18959_Content_77 = {
    Text = "不意にかすかな鳴き声が聞こえてきた。\n高くなったり低くなったり、抑揚をつけたりしている。"
  },
  AvgDialog_18959_Content_78 = {
    Text = "どうして鼠が……<Big:ブラウン！？>"
  },
  AvgDialog_18959_Content_8 = {
    Text = "手伝ってくれるなら、お前の財布とナントカ証を返して、秘密にしといてやるよ。もし手伝ってくれなかったら……フフン！"
  },
  AvgDialog_18959_Content_80 = {
    Text = "鳴き声からすると……近くにいるみたい。"
  },
  AvgDialog_18959_Content_81 = {
    Text = "急いで立ち上がって周囲を見て回ると、墓碑の後ろの草むらでずんぐりと太った鼠を見つけた。"
  },
  AvgDialog_18959_Content_82 = {
    Text = "グゥグゥ……グゥー……"
  },
  AvgDialog_18959_Content_83 = {
    Text = "この体格、それにこの毛の色……本当にブラウンだ！！"
  },
  AvgDialog_18959_Content_84 = {
    Text = "あなたと24は同時に驚きの声を上げた。"
  },
  AvgDialog_18959_Content_85 = {
    Text = "蝋人形館の事件以来、姿を消していたこの鼠は、あなたたちに見つかっても起きなかった。"
  },
  AvgDialog_18959_Content_86 = {
    Text = "まるで大冒険を終えたばかりで、このとき旅の終点で疲れきって眠りこけているようだ。"
  },
  AvgDialog_18959_Content_87 = {
    Text = "グゥ……スー……スヤスヤ……"
  },
  AvgDialog_18959_Content_88 = {
    Text = "何かを抱えているみたい……"
  },
  AvgDialog_18959_Content_9 = {
    Text = "<Big:《バルト海の春》！>"
  },
  AvgDialog_18959_Content_90 = {
    Text = "シルバーコアだ。\nジェンキンのシルバーコア。"
  },
  AvgDialog_18959_Content_91 = {
    Text = "小さな前肢がシルバーコアをしっかり抱いている。\nまだ磨かれていないそれは、曇ったような微かな光を放っている。"
  },
  AvgDialog_18959_Content_92 = {
    Text = "だがその微かな光の下から、この上なく陽気で活発な心臓の鼓動が聞こえたような気がした。"
  },
  AvgDialog_18959_Content_93 = {
    Text = "久しぶりだね、ジェンキン。"
  },
  AvgDialog_18959_Content_94 = {
    Text = "空がようやく晴れてきた。空高く昇った太陽から金色の光が降り注ぎ、ちょうどよい暖かさが伝わってくる。"
  },
  AvgDialog_18959_Content_95 = {
    Text = "風が吹いて新鮮な土の香りを運んできた。\nあなたと24は暖かい日差しを浴び、顔を見合わせて笑った。"
  },
  AvgDialog_18959_Content_96 = {
    Text = "行こう、24さん。"
  },
  AvgDialog_18959_Content_97 = {
    Text = "連日の暗雲がようやく晴れた。\nあなたたちの冒険物語は始まったばかりだ。"
  },
  AvgDialog_18960_Content_1 = {
    Text = "静かな崩壊"
  },
  AvgDialog_18960_Content_10 = {
    Text = "でも今、選択の余地はないわ。"
  },
  AvgDialog_18960_Content_11 = {
    Text = "やってみよう"
  },
  AvgDialog_18960_Content_12 = {
    Text = "%player%、少し冷静になって。"
  },
  AvgDialog_18960_Content_13 = {
    Text = "この先は融蝕液に埋もれているわ。\nたとえ覚醒体でも長時間浸かっていると影響を受けるわ。"
  },
  AvgDialog_18960_Content_14 = {
    Text = "今はもう通常の道筋では帰れないから、他の方法を考えないと。"
  },
  AvgDialog_18960_Content_15 = {
    Text = "他の方法……他の通路……"
  },
  AvgDialog_18960_Content_16 = {
    Text = "あった！"
  },
  AvgDialog_18960_Content_17 = {
    Text = "ほら、そこに換気口がある。"
  },
  AvgDialog_18960_Content_18 = {
    Text = "あなたたちはジェンキンの視線を追って、頭上にある小さな換気口を見上げた。"
  },
  AvgDialog_18960_Content_19 = {
    Text = "あそこなら確かに館長室に通じている可能性があるし、融蝕液も届かない……"
  },
  AvgDialog_18960_Content_2 = {
    Text = "4:15，ロジャーズ蝋人形館"
  },
  AvgDialog_18960_Content_20 = {
    Text = "だめよ、あの通路は狭すぎて、私たちは入れない。"
  },
  AvgDialog_18960_Content_21 = {
    Text = "あたしなら潜れるよ。"
  },
  AvgDialog_18960_Content_22 = {
    Text = "忘れてもらっちゃ困るな、あたしは「ネズミ」だよ。"
  },
  AvgDialog_18960_Content_23 = {
    Text = "チュー！"
  },
  AvgDialog_18960_Content_24 = {
    Text = "だめよ、危険すぎる。鍵が今も館長室にあるという保証はないし、この換気口だって果たして——"
  },
  AvgDialog_18960_Content_25 = {
    Text = "チッ、ごちゃごちゃうるさいな。\nラモンナはもっときっぱりした人だと思ってたよ。"
  },
  AvgDialog_18960_Content_26 = {
    Text = "現実の問題を整理してやるよ。第一に、今は他に方法がないんだろ？ここで死ぬのを待つより、一か八か試してみたほうがいい。"
  },
  AvgDialog_18960_Content_27 = {
    Text = "第二に、ブラウンと一緒に行く。\nあたしが指図して、鍵を取ってくるのはこいつの役目。"
  },
  AvgDialog_18960_Content_28 = {
    Text = "キーッ！チューチュー！"
  },
  AvgDialog_18960_Content_29 = {
    Text = "第三に……"
  },
  AvgDialog_18960_Content_3 = {
    Text = "あなたたちは息を切らし、よろめきながら廃墟の中を走り抜けた。"
  },
  AvgDialog_18960_Content_30 = {
    Text = "今回はあんたたちにいろいろ迷惑をかけた。\n姉ちゃんはあたしのせいで鞭打たれたし。"
  },
  AvgDialog_18960_Content_31 = {
    Text = "だから……"
  },
  AvgDialog_18960_Content_32 = {
    Text = "あたしにも少しは手伝わせてくれよ。\nずっとお世話されっぱなしじゃ耐えられない。"
  },
  AvgDialog_18960_Content_33 = {
    Text = "そう言うと、ジェンキンはぱっと換気口に跳び上がった。\n\nいつもホワイトチャペル地区の入り組んだ建物の間を行き来していたように、一瞬で姿を消した。"
  },
  AvgDialog_18960_Content_34 = {
    Text = "ジェンキン……！いつも私の言うことを聞かないんだから……"
  },
  AvgDialog_18960_Content_35 = {
    Text = "心配しないで、24さん。\nジェンキンは私たちよりすばしっこいし、きっと大丈夫よ。"
  },
  AvgDialog_18960_Content_36 = {
    Text = "……彼女を信じているわ。"
  },
  AvgDialog_18960_Content_4 = {
    Text = "ようやく前方に重々しい扉が見えた。\nここを押し開ければ——"
  },
  AvgDialog_18960_Content_5 = {
    Text = "やばい、鍵がかかってる。"
  },
  AvgDialog_18960_Content_6 = {
    Text = "前方は既に黒い海と化し、危険がひしひしと迫っており、逃げ場はない。"
  },
  AvgDialog_18960_Content_7 = {
    Text = "ウィリアムが言っていた扉のようだけど……鍵は館長室にあるはず。"
  },
  AvgDialog_18960_Content_8 = {
    Text = "行けない"
  },
  AvgDialog_18960_Content_9 = {
    Text = "ここは融蝕液だらけで……覚醒体でも長時間浸かっていると死んでしまう。"
  },
  AvgDialog_18961_Content_10 = {
    Text = "あーあ、眠くて死にそう！"
  },
  AvgDialog_18961_Content_100 = {
    Text = "次の瞬間、彼女は手首を軽く振った。\n熱い蝋が急に注がれ、白い腕に荒々しく赤い花が咲いた。"
  },
  AvgDialog_18961_Content_101 = {
    Text = "ぎゃああああ——！"
  },
  AvgDialog_18961_Content_102 = {
    Text = "わあ……きれいな模様だね。"
  },
  AvgDialog_18961_Content_103 = {
    Text = "ジョージはうるさいネズミが嫌い。\n蝋を全部彼女の口に詰め込んで。"
  },
  AvgDialog_18961_Content_104 = {
    Text = "宙に浮いた燭台がジェンキンの前まで飛んできた。\n蒸気でジェンキンの顔が真っ赤に炙られる。"
  },
  AvgDialog_18961_Content_105 = {
    Text = "燭台の中には熱い蝋が満ちていて、今にも溢れ出しそうだ。"
  },
  AvgDialog_18961_Content_106 = {
    Text = "<Shake:ウソつき……痛くないって言ったくせに……>"
  },
  AvgDialog_18961_Content_107 = {
    Text = "あ～ら、ごめんなさい。もう長いこと人間やってないから、そんなに辛いとは思わなかったわ～"
  },
  AvgDialog_18961_Content_108 = {
    Text = "完璧だ。\n二人ともきて、彼女の口をこじ開けろ。"
  },
  AvgDialog_18961_Content_109 = {
    Text = "次に蝋を注ぎ込めば、下水道の臭いネズミは永遠に黙るだろう。"
  },
  AvgDialog_18961_Content_11 = {
    Text = "次にこんなにグズグズしてたら、あんたも棺桶に入れるからね～。"
  },
  AvgDialog_18961_Content_110 = {
    Text = "やめて……やめろ！彼女は何の関係もない……"
  },
  AvgDialog_18961_Content_111 = {
    Text = "<Small:姉ちゃん……痛いよ……本当に痛いよ……>"
  },
  AvgDialog_18961_Content_112 = {
    Text = "いやだ……やめろ、気が変わった、死にたくない！来るな……！"
  },
  AvgDialog_18961_Content_114 = {
    Text = "……待って。"
  },
  AvgDialog_18961_Content_115 = {
    Text = "混乱の中で、突然軽いため息が聞こえた。"
  },
  AvgDialog_18961_Content_116 = {
    Text = "どうか……待ってください。"
  },
  AvgDialog_18961_Content_12 = {
    Text = "すみません、パンディアさん……"
  },
  AvgDialog_18961_Content_13 = {
    Text = "<Big:パンディア様——！！>"
  },
  AvgDialog_18961_Content_14 = {
    Text = "女の姿が雲のように漂い、長いスカートの裾がねじれて白い光をはね返した。彼女はパンディアの前まで這って平伏した。"
  },
  AvgDialog_18961_Content_15 = {
    Text = "パンディア様！どうか24にそんなことをなさらないでください。\n罰するなら……"
  },
  AvgDialog_18961_Content_16 = {
    Text = "どうぞ私を！"
  },
  AvgDialog_18961_Content_18 = {
    Text = "気が変わったわ。\nあんたたちはよくやってくれたから、下がって。"
  },
  AvgDialog_18961_Content_19 = {
    Text = "私を責めるに忍びないことは分かります。\nパンディア様はいつもお優しいので……"
  },
  AvgDialog_18961_Content_2 = {
    Text = "よし、全員揃ったわね。\nこれでミサゴにたっぷりお礼ができるわ。"
  },
  AvgDialog_18961_Content_21 = {
    Text = "あたしの親愛なる、最愛のハニー。\nまず、あたしの足を放してもらえるかしら？"
  },
  AvgDialog_18961_Content_22 = {
    Text = "何もかもお言いつけ通りにいたします、パンディア様。"
  },
  AvgDialog_18961_Content_23 = {
    Text = "いい子ね。じゃあその調子で……回れ右をして、そのまま前に十歩進んで、この部屋を出て、二度と振り返らないで。"
  },
  AvgDialog_18961_Content_24 = {
    Text = "言っている意味が分かる？"
  },
  AvgDialog_18961_Content_25 = {
    Text = "分かりました……パンディア様が恋しくなります……\nいえ、今すでに恋しくなってきました！"
  },
  AvgDialog_18961_Content_26 = {
    Text = "女は背を向け、去り際にドアを閉めることを忘れなかった。"
  },
  AvgDialog_18961_Content_27 = {
    Text = "ふぅー……まったく頭が痛いわね。"
  },
  AvgDialog_18961_Content_28 = {
    Text = "ドアがしっかり閉まっているのを確認した後、パンディアは深呼吸すると、いつもの陽気さを取り戻した。"
  },
  AvgDialog_18961_Content_29 = {
    Text = "さて皆さん、さっきどこまで話したかしらー？"
  },
  AvgDialog_18961_Content_3 = {
    Text = "でもね、この瞬間を待つのはやっぱり、ちょ～っと——\nいえ、超～長かったわ。"
  },
  AvgDialog_18961_Content_30 = {
    Text = "息が……苦しい。"
  },
  AvgDialog_18961_Content_32 = {
    Text = "う、動くんじゃない、今化粧をしているんだから。"
  },
  AvgDialog_18961_Content_33 = {
    Text = "しまった、口元がぼやけてしまった。\nうーむ……"
  },
  AvgDialog_18961_Content_34 = {
    Text = "あんたは、ロジャーズ……"
  },
  AvgDialog_18961_Content_35 = {
    Text = "冷たい指があなたの唇の端を拭った。\n鼻をつく腐った油脂の匂いがした。"
  },
  AvgDialog_18961_Content_36 = {
    Text = "体を動そうとしたが、全身が冷たい器具の中に閉じ込められていることに気づいた。"
  },
  AvgDialog_18961_Content_37 = {
    Text = "これでよし。\n君は実に、か、完璧な蝋人形素材だね。"
  },
  AvgDialog_18961_Content_38 = {
    Text = "%player%、やっと目が覚めたな！"
  },
  AvgDialog_18961_Content_39 = {
    Text = "放せ……うっ！"
  },
  AvgDialog_18961_Content_4 = {
    Text = "24、あたしの最愛の24、早くいらっしゃい～。"
  },
  AvgDialog_18961_Content_40 = {
    Text = "動かないでね、あんたたちを固定するのにずいぶん苦労したんだから。"
  },
  AvgDialog_18961_Content_41 = {
    Text = "あそこにある棺桶が見える？あんたたちのために特別に用意したの。\nもうすぐ新しい人生が始まるのよ～"
  },
  AvgDialog_18961_Content_42 = {
    Text = "ただし蝋人形としてだけどね、ふふふ。\n今回はどんなテーマにしようかしら？うーん……"
  },
  AvgDialog_18961_Content_43 = {
    Text = "どこにもいない、チャーリーの大事なトラ猫ちゃん～。"
  },
  AvgDialog_18961_Content_44 = {
    Text = "トラ猫ちゃん、トラ猫ちゃん～。"
  },
  AvgDialog_18961_Content_45 = {
    Text = "ラモンナ……ラモンナ！？やめて、歌わないで……"
  },
  AvgDialog_18961_Content_46 = {
    Text = "あたしが目を覚ましてからずっとこの調子なんだ。\n延々と繰り返し歌ってる。"
  },
  AvgDialog_18961_Content_47 = {
    Text = "あんたの相棒はもう蝋人形になっちゃったわよ。\nロジャーズ様が一時間かけて作ったの。"
  },
  AvgDialog_18961_Content_48 = {
    Text = "トラ猫ちゃん！ニャー！"
  },
  AvgDialog_18961_Content_49 = {
    Text = "どう、気に入った？超可愛いでしょ～？"
  },
  AvgDialog_18961_Content_5 = {
    Text = "……はい、パンディア様。"
  },
  AvgDialog_18961_Content_50 = {
    Text = "ペッ、その汚い手をラモンナから離せ！"
  },
  AvgDialog_18961_Content_51 = {
    Text = "ロジャーズ、工房であたしを気絶させたのはお前だな。"
  },
  AvgDialog_18961_Content_52 = {
    Text = "お前はアイギスと、マイクを殺した。\n姉ちゃんが行方不明になったのも……"
  },
  AvgDialog_18961_Content_53 = {
    Text = "アイギスって何？"
