  AvgDialog_19028_Content_14 = {
    Text = "ラモンナはいる？"
  },
  AvgDialog_19028_Content_15 = {
    Text = "なぜか、いつも冷静なドールの口調に、何やら焦りが感じられた。"
  },
  AvgDialog_19028_Content_16 = {
    Text = "いるけど。\n何かあったの？"
  },
  AvgDialog_19028_Content_17 = {
    Text = "さっき通信記録を検索していたんだけど、エリカにある人のことを調べてもらった？"
  },
  AvgDialog_19028_Content_18 = {
    Text = "女性、自称「水仙夫人」、年齢は見た目で二十八歳前後、長い銀髪で、骨董品の商いをしている。"
  },
  AvgDialog_19028_Content_19 = {
    Text = "ええ、でもエリカはアーカイブに関連資料がないと言っていたわ。"
  },
  AvgDialog_19028_Content_2 = {
    Text = "まず、攻撃を仕掛けてきたのはあなたたちだからね。"
