  AvgDialog_19090_Content_15 = {
    Text = "死にたくない"
  },
  AvgDialog_19090_Content_16 = {
    Text = "一瞬、死のような静寂が広がった。"
  },
  AvgDialog_19090_Content_2 = {
    Text = "海踊教団のノートには、<Blue:星辰正しき刻>の重要性が何度も強調されているわ。\n降生の儀式も特定の時間に行わなければならないの。あの女が私を眠らせる理由もそれよ。"
  },
  AvgDialog_19090_Content_3 = {
    Text = "船長は彼の神格の成長が天体の運行と関係があると推測。\nシレストは船を中心にこの隔離された密境を作った。"
  },
  AvgDialog_19090_Content_4 = {
    Text = "当てた。真の空から離れて、神も静まり返る。\n密境で星辰正しき刻をやり過ごせば、神は永遠に眠るかもしれない。"
  },
  AvgDialog_19090_Content_5 = {
    Text = "待って、シレスト？"
  },
  AvgDialog_19090_Content_6 = {
    Text = "誰か説明してくれませんか？「シレスト」とは何者でしょう？"
  },
  AvgDialog_19090_Content_7 = {
    Text = "え？説明していなかった？"
  },
  AvgDialog_19090_Content_8 = {
    Text = "シレストはキャプテンの相棒であり、覚醒体でもある。\n彼女が沈むべきだったソナニール号の航海を制御し、この密境を築いた。"
  },
  AvgDialog_19090_Content_9 = {
    Text = "私たちが陸地に戻れるかどうかも彼女次第ですか？"
  },
  AvgDialog_19091_Content_1 = {
    Text = "マーフィーの気分が落ち込み、どう慰めていいか分からないが、ラモンナは空の海鳥をぼーっと見ていた。"
  },
  AvgDialog_19091_Content_10 = {
    Text = "王立天文台の計算によると、月が近地点に達するのは<Blue:聖パトリックの日>前後のはずだ。\n現在の月相は科学的に説明できない。"
  },
  AvgDialog_19091_Content_11 = {
