  },
  AvgDialog_19091_Content_12 = {
    Text = "はい、月がとても大きい夜でした。\n月がとても明るく、他の星座は見えませんでした。"
  },
  AvgDialog_19091_Content_13 = {
    Text = "な、何！？まさか今日だなんて"
