  AvgDialog_22708_Content_40 = {
    Text = "お前は俺より小さいんだから……気をつけろよ！大男の背中には座る場所なんてないぞ。"
  },
  AvgDialog_22708_Content_41 = {
    Text = "オレッタは仲間と一緒がいい！"
  },
  AvgDialog_22708_Content_42 = {
    Text = "おい！なんでお前の体はぬるぬるしてるんだ！？泳げる奴は登ってくるな！"
  },
  AvgDialog_22708_Content_43 = {
    Text = "巨獣は気道から轟音の響きを発し、笑い声と希望を乗せて水面に躍り出た。"
  },
  AvgDialog_22708_Content_44 = {
    Text = "夜明けの光が雲と水しぶきを突き抜け、海と巨獣と冒険者たちを赤とピンクのベールで包み込む。"
  },
  AvgDialog_22708_Content_45 = {
    Text = "た、高いーー！"
  },
  AvgDialog_22708_Content_47 = {
    Text = "探長G、海洋精霊、真夜中の義賊とその助手が協力して少女を捕まえ、巨獣の背から滑り落ちないようにした。"
  },
  AvgDialog_22708_Content_48 = {
    Text = "彼らは楽しそうに笑いながら、互いの服に水を塗り合った。"
  },
  AvgDialog_22708_Content_49 = {
    Text = "その時、勇敢な少女が突然じっとこちらを見て、晴れやかで優しい笑顔を浮かべた。"
  },
  AvgDialog_22708_Content_5 = {
    Text = "まあ、ちょっとした試練よ。"
  },
  AvgDialog_22708_Content_50 = {
    Text = "花期を逃したユリが、"
  },
  AvgDialog_22708_Content_51 = {
    Text = "ようやく咲く時を迎えた。"
  },
  AvgDialog_22708_Content_6 = {
    Text = "カーシアの顔に笑みが広がると、暗流の音が全員の耳に聞こえてきた。"
  },
  AvgDialog_22708_Content_7 = {
    Text = "流れ込め！洪水！フーディーニ大師のラストショーを完成させるんだ！"
  },
  AvgDialog_22708_Content_8 = {
    Text = "水位は急速に上昇し、すぐに子供たちの足の甲、そしてふくらはぎ……最後に太ももまで水が上がり、彼らは歩くのが難しくなった。"
  },
  AvgDialog_22708_Content_9 = {
    Text = "カーシア！何やってんだ！？俺たちを溺れさせる気かよ！？"
  },
  AvgDialog_23346_Content_1 = {
    Text = "黒い粘液が潮のように引き、部屋の中は再び静寂を取り戻した。"
  },
  AvgDialog_23346_Content_10 = {
    Text = "血のように赤い薔薇の花弁が舞い散り、濃厚で腐臭を帯びた花の香りが黒い私室に満ちる。"
  },
  AvgDialog_23346_Content_11 = {
    Text = "仮面をかぶった黒い影が、音もなくソレール夫人の背後に現れた。"
  },
  AvgDialog_23346_Content_12 = {
    Text = "お邪魔いたします、紳士淑女の皆様。これより次の演目をどうぞ——"
  },
  AvgDialog_23346_Content_15 = {
    Text = "鮮やかな薔薇がソレールの胸を貫き、花弁に宿る露が夜の闇に青白く光った。"
  },
  AvgDialog_23346_Content_16 = {
    Text = "こ、これは……何です……？"
  },
  AvgDialog_23346_Content_17 = {
    Text = "黒い影は一瞬で姿を消し、残されたソレールは胸元から溢れる血を呆然と見つめる。"
  },
  AvgDialog_23346_Content_18 = {
    Text = "ああ！！夫人、胸が……！"
