  AvgDialog_23347_Content_6 = {
    Text = "■<Yellow:調査結果>\n\n身元不明の@2出現により調査は中断。守秘者はこれに関連する大部分の記憶を喪失。\n<Red:守秘者は強制的に密境から排除され、生命の危機に瀕している。>"
  },
  AvgDialog_23348_Content_1 = {
    Text = "お二人とも、お待ちください。"
  },
  AvgDialog_23348_Content_2 = {
    Text = "その老紳士に至急伝えたいことがあります。\n取り次いでいただけませんか？"
  },
  AvgDialog_23348_Content_3 = {
    Text = "申し訳ないですが、旦那様は重い伝染病を患っており、客に会うことはできません。"
  },
  AvgDialog_23348_Content_4 = {
    Text = "馬車越しに話すだけでいいわ。一歩も近づかないから。"
  },
  AvgDialog_23348_Content_5 = {
    Text = "だが、全身武装の大男は取り合おうとしなかった。ここは西区でも特に賑やかな繁華街で、戦闘を始めれば全員の注目を集めるだろう。"
  },
  AvgDialog_23348_Content_6 = {
    Text = "不必要な厄介ごとは避けたい。\nそう思わずにはいられなかった。"
  },
  AvgDialog_23348_Content_7 = {
    Text = "じゃあ、こっそり後をつけてみよう。彼らが何者か確かめないと。"
  },
  AvgDialog_23349_Content_1 = {
    Text = "馬車を追い、七度八度と曲がり道を抜けるうちに、いつの間にか市街を離れ、荒れ果てた郊外へと出ていた。"
  },
  AvgDialog_23349_Content_10 = {
    Text = "とにかく入ってみましょう。"
  },
  AvgDialog_23349_Content_2 = {
    Text = "濃い霧があたり一面を覆い、前方にはかすかに黒い馬車の輪郭が揺れて見えるばかり。"
  },
  AvgDialog_23349_Content_3 = {
    Text = "その輪郭は徐々に薄れ、ついには完全に見失ってしまった。"
  },
  AvgDialog_23349_Content_4 = {
    Text = "なんて場所だ……最近のロンディニウムはどこも霧ばかりで、警察も調査員も仕事にならないね。"
  },
  AvgDialog_23349_Content_5 = {
    Text = "濃霧を抜けると、陰鬱な雲に覆われた古い屋敷が遠くに姿を現した。"
  },
  AvgDialog_23349_Content_6 = {
    Text = "外壁の木材はあちこちに裂け目があり、そこから重苦しい気配が漏れ出しているようだった。"
  },
  AvgDialog_23349_Content_7 = {
    Text = "濃霧、廃屋、謎の死を遂げた社交界の花、正体不明の老紳士……小説に出てきそうな要素が全部そろっているね。"
  },
  AvgDialog_23349_Content_8 = {
    Text = "中にあの老紳士がいると思う？"
  },
  AvgDialog_23349_Content_9 = {
    Text = "このあたりは荒れ果てて、見渡すかぎり何もないわ。\n他に選択肢はなさそう。"
  },
  AvgDialog_23351_Content_1 = {
    Text = "まもなく開演だ。とにかく戻ろう。"
  },
  AvgDialog_23351_Content_10 = {
    Text = "……お目覚めになったのですか？"
  },
  AvgDialog_23351_Content_12 = {
    Text = "慌てて振り返ったが、背後には誰もいない。"
  },
  AvgDialog_23351_Content_13 = {
    Text = "ソレール夫人？"
  },
  AvgDialog_23351_Content_14 = {
    Text = "彼女はすぐに平静を取り戻し、作り笑いを浮かべた。"
  },
  AvgDialog_23351_Content_15 = {
    Text = "知り合ってまだ30分も経っていませんのに、あなたはもう三度も謝罪されておりますわ。"
  },
  AvgDialog_23351_Content_16 = {
    Text = "本当に謝りたいのでしたら、こちらのほうが誠意があるのでは？"
  },
  AvgDialog_23351_Content_17 = {
    Text = "ソレールは杯の中の黄金の酒を揺らしてみせた。"
  },
  AvgDialog_23351_Content_18 = {
    Text = "待ち人は来ませんでした。だから、わたくしとゲームをしましょう。\nわたくしが三つ質問するわ。答えられなければ……"
  },
  AvgDialog_23351_Content_19 = {
    Text = "彼女は杯を卓に置き、傍らのワゴンに積まれたシャンパンを指さした。"
  },
  AvgDialog_23351_Content_2 = {
    Text = "やっと戻られましたね、私の騎士様。"
  },
  AvgDialog_23351_Content_20 = {
    Text = "一杯飲んでもらいます。"
  },
  AvgDialog_23351_Content_3 = {
    Text = "ソレールは微笑みながら隅に腰かけ、相変わらず眩いほどの美しさを放っていた。"
  },
  AvgDialog_23351_Content_4 = {
    Text = "無事でよかった。"
  },
  AvgDialog_23351_Content_5 = {
    Text = "守ってくれるんでしょう？ずっと待っていましたよ。"
  },
  AvgDialog_23351_Content_6 = {
    Text = "彼女は何気なく笑ったが、その声音には微かな寂しさが混じっていた。"
  },
  AvgDialog_23351_Content_7 = {
    Text = "申し訳ありませんでした。ソレール夫人……"
  },
  AvgDialog_23351_Content_8 = {
    Text = "<Red:フフ。>"
  },
  AvgDialog_23351_Content_9 = {
    Text = "ソレールはふと君の背後を見据え、瞳に不安を宿した。"
  },
  AvgDialog_23352_Content_1 = {
    Text = "扉を押し開けた瞬間、鼻をつく腐った花の香りが襲ってきた。広間には赤いバラが植えられていたが、すでに枯れかけている。"
  },
  AvgDialog_23352_Content_10 = {
    Text = "ラモンナは外の空を一瞥した。"
  },
  AvgDialog_23352_Content_11 = {
    Text = "今日の調査はここまでにしましょうか。この屋敷の場所は記録しておいたから、戻って所有者を調べましょう。"
  },
  AvgDialog_23352_Content_12 = {
    Text = "うん。明日の行動はいつも通りだね。"
  },
  AvgDialog_23352_Content_13 = {
    Text = "まずはカレンから招待状を手に入れて、それから私が二階でソレール夫人を守り、君が一階を見張る。"
  },
  AvgDialog_23352_Content_14 = {
    Text = "運が良ければ、馬車に乗っていたあの老紳士にも会えるかもしれない。"
  },
  AvgDialog_23352_Content_2 = {
    Text = "うっ……あの仮面の影と同じ匂い。"
  },
  AvgDialog_23352_Content_3 = {
    Text = "ここには何もない……どうやら長いこと人が住んでいないみたいね。"
  },
  AvgDialog_23352_Content_4 = {
    Text = "あなたは薄暗く湿った広間を見回した。空っぽで、蜘蛛の巣が隅で揺れている。地面には枯れた花びらと葉が散らばっていた。"
  },
  AvgDialog_23352_Content_5 = {
    Text = "あれ？ここに絵が掛かってる。"
  },
  AvgDialog_23352_Content_6 = {
    Text = "階段の曲がり角に精巧に額装された肖像画が掛かっており、柔らかく朦朧とした筆致で華やかな装いの婦人が描かれていた。"
  },
  AvgDialog_23352_Content_7 = {
    Text = "化粧された顔は美しいが、目尻は垂れ、薄い唇は固く結ばれ、どこか陰鬱で不安げな表情をしていた。"
  },
  AvgDialog_23352_Content_8 = {
    Text = "テンペラ画かしら？今ではもうほとんど使われない技法ね。"
  },
  AvgDialog_23352_Content_9 = {
    Text = "妙だな。この絵だけは埃ひとつ積もってない。誰かが定期的に手入れしてるみたい。"
  },
  AvgDialog_23353_Content_10 = {
    Text = "ラモンナは眉をひそめ、目には深い憂慮が浮かんでいた。"
  },
  AvgDialog_23353_Content_11 = {
    Text = "ラモンナ……"
  },
  AvgDialog_23353_Content_12 = {
    Text = "もう一度密境に入らない？\n私が二階でソレール夫人を守り、ラモンナが一階を見張る。"
  },
  AvgDialog_23353_Content_13 = {
    Text = "人工密境はいつでも行ける観光地ではないわよ。\nあなたたちに今、必要なのは休息よ。"
  },
  AvgDialog_23353_Content_14 = {
    Text = "でも、調査を進めるために<Yellow:非常手段>も必要かもね……"
  },
  AvgDialog_23353_Content_15 = {
    Text = "人工密境に入ること自体、もう十分に無謀だと思ったけど。"
  },
  AvgDialog_23353_Content_16 = {
    Text = "ドールの普段、無表情な顔に『狡猾』とも言える笑みが浮かんだ。"
  },
  AvgDialog_23353_Content_17 = {
    Text = "もっといい案があるわ。あとはあなたたちがそれに賭けるかどうかよ。"
  },
  AvgDialog_23353_Content_18 = {
    Text = "ブリンズバーグ通り，23:00"
  },
  AvgDialog_23353_Content_19 = {
    Text = "ハハハハ！実に素晴らしい夜に、美味しい酒だ！"
  },
  AvgDialog_23353_Content_2 = {
    Text = "それで？劇場で仮面をつけた黒い影以外の手がかりは見つかった？"
  },
  AvgDialog_23353_Content_20 = {
    Text = "ニコラスさん。この香り高い古酒が私を牢獄から救い出してくれた、まさに恩人ですよ。"
  },
  AvgDialog_23353_Content_21 = {
    Text = "ミサゴ大学を監獄に例えるなら、あなたの養女はそれこそ看守長ですかね？ハハハ……"
  },
  AvgDialog_23353_Content_22 = {
    Text = "デクスターの頬は赤く染まり、目はとろんとしていた。彼は人差し指を唇に当てる。"
  },
  AvgDialog_23353_Content_23 = {
    Text = "シー……今回はこっそり抜け出しましたから、絶対にラモンナに見つかっちゃダメなんですよ。"
  },
  AvgDialog_23353_Content_25 = {
    Text = "羨ましいですよ、デクスターさん。あなたには本当に気遣ってくれる家族がいる。"
  },
  AvgDialog_23353_Content_26 = {
    Text = "ですが、私はどうです？つい先日に最愛の人を失い、彼女の骸はすでに冷たく、父も死んだ！"
