  AvgDialog_23366_Content_2 = {
    Text = "うっ……！"
  },
  AvgDialog_23366_Content_3 = {
    Text = "んんっ……"
  },
  AvgDialog_23366_Content_4 = {
    Text = "繁華街が目の前に広がる。すでに夜が近く、街灯が次々と灯り、道沿いの商店の看板を明るく照らしていた。"
  },
  AvgDialog_23366_Content_5 = {
    Text = "人々は忙しなく行き交い、笑い声と馬車や車の音が入り混じり、陽気な交響曲を奏でている。"
  },
  AvgDialog_23366_Content_6 = {
    Text = "久しぶりに西区へ来たけど、やっぱり変わらないね！"
  },
  AvgDialog_23366_Content_7 = {
    Text = "リンカン通りを真っすぐ行くと、小さな菓子屋があってね。世界一美味しいケーキなんだ！"
  },
  AvgDialog_23366_Content_8 = {
    Text = "人工密境で食べるケーキって、どんな味なんだろう……"
  },
  AvgDialog_23366_Content_9 = {
    Text = "ラモンナは無表情のまま腕時計に視線を落とした。"
  },
  AvgDialog_23367_Content_1 = {
    Text = "堕ちた審判"
  },
  AvgDialog_23367_Content_10 = {
    Text = "ふふ、あの連中は相変わらず食欲旺盛ですわね。すべてに同意？ そんなことをしたら、これまでの努力が無駄になるではないですか。"
  },
  AvgDialog_23367_Content_11 = {
    Text = "そんなのはごめんよ？"
  },
  AvgDialog_23367_Content_12 = {
    Text = "もし拒否すれば、ミサゴ大学は条項に基づき、すぐに二度目の覚醒を中止し、あなたの行為を公表します。"
  },
  AvgDialog_23367_Content_13 = {
    Text = "実際、あなたには選択肢が残されていないのです、ソレール夫人。"
  },
  AvgDialog_23367_Content_14 = {
    Text = "選択肢がない？あなたは私を甘く見すぎていますわね。"
  },
  AvgDialog_23367_Content_15 = {
    Text = "世に公表する……融蝕の存在を？それとも覚醒体の存在をかしら？"
  },
  AvgDialog_23367_Content_16 = {
    Text = "どちらを暴くか、あなたたちで選んでごらんなさい？"
  },
  AvgDialog_23367_Content_17 = {
    Text = "その瞳は笑っていても、底知れぬ冷たさが宿っていた。あなたは彼女を本気で怒らせたと悟る。"
  },
  AvgDialog_23367_Content_18 = {
    Text = "だがこの反応すら、上層部は計算済み。あなたは用意された台詞を搾り出すしかなかった。"
  },
  AvgDialog_23367_Content_19 = {
    Text = "恐れ入ります、ソレール夫人。どうかこの交渉を脅迫とは思わないでください。これは互恵的な協力であり、上層部は誠意を持って……"
  },
  AvgDialog_23367_Content_2 = {
    Text = "契約……なるほど。\n彼があなたに特別な力を与え、代わりにあなたは彼のために働く。"
  },
  AvgDialog_23367_Content_20 = {
    Text = "<Red:つまらない。眠くなってきたわ。>"
  },
  AvgDialog_23367_Content_21 = {
    Text = "気づけば音楽は止まり、劇場は巨大な墓場のように沈黙していた。"
  },
  AvgDialog_23367_Content_22 = {
    Text = "役者も観客も、カレンすらも動かず、虚ろな瞳であなたとソレールを見つめている。"
  },
  AvgDialog_23367_Content_23 = {
    Text = "……え？"
  },
  AvgDialog_23367_Content_24 = {
