  AvgDialog_23367_Content_29 = {
    Text = "あなたの言う存在、それはまさか……？"
  },
  AvgDialog_23367_Content_3 = {
    Text = "だからあの分身は彼にそっくりだったんですね。あなたは彼の力を借りていた……"
  },
  AvgDialog_23367_Content_30 = {
    Text = "ミサゴ大学を利用してわたくしを牽制しようとした上層部は賢いですわ。でも一つ、計算を誤った――あなたの存在を、見落としたのよ。"
