  AvgDialog_23841_Content_34 = {
    Text = "その先輩は今、通信に接続できますか？"
  },
  AvgDialog_23841_Content_35 = {
    Text = "……残念だな。\n君がミサゴ大学に入る前に、彼は任務中に亡くなった。"
  },
  AvgDialog_23841_Content_36 = {
    Text = "待ちなさい！ラモンナ、あなたまさか……！"
  },
  AvgDialog_23841_Content_37 = {
    Text = "ええ、敵は私たちの救援までは待ってくれないようだから。"
  },
  AvgDialog_23841_Content_38 = {
    Text = "魚人たちは、ソナニール号をどうにかしようとすることをやめて、あなたたちに武器を向け始めた。\n包囲がせまり、あなたとラモンナは船体側に追いつめられる。"
  },
  AvgDialog_23841_Content_39 = {
    Text = "ラモンナは一つ深呼吸をすると、船の縁から降りている梯子に慎重に手を伸ばした。"
  },
  AvgDialog_23841_Content_40 = {
    Text = "魚人たちが数メートル弾かれたのとは違って、ラモンナの手はしっかりと船体に触れていた。\nあなたは彼女と目を合わせ、自身も船体に触れた。"
  },
  AvgDialog_23841_Content_41 = {
    Text = "微かな抵抗を感じて手を止めたが、それはすぐに消えた。\n鉄の冷たさが手袋を通して伝わり、頭まで凍るように感じた。"
  },
  AvgDialog_23841_Content_42 = {
    Text = "このソナニール号は、<Yellow:あなたたちを拒絶していない>。"
  },
  AvgDialog_23841_Content_43 = {
    Text = "私たちは今から船に乗るわ。"
  },
  AvgDialog_23841_Content_5 = {
    Text = "包囲網が最小限に縮められたが、魚人の怪物はそれ以上攻めてこなかった。\n一定の位置であなたたちと対峙し、口から奇妙な呟きを吐き続けた。"
