  AvgDialog_23842_Content_12 = {
    Text = "わ、わたくし、あなたの名前を聞いたことがないかも……"
  },
  AvgDialog_23842_Content_13 = {
    Text = "マーフィーは恥ずかしそうに頭をかいて、船長の後ろに隠れた。そして、この場の挨拶を唯一の大人に任せた。"
  },
  AvgDialog_23842_Content_14 = {
    Text = "私は%player%、ミサゴ大学の学生だよ。"
  },
  AvgDialog_23842_Content_15 = {
