  AvgDialog_23843_Content_10 = {
    Text = "ラモンナ！気をつけて！"
  },
  AvgDialog_23843_Content_11 = {
    Text = "あなたは銀の鍵を取り出し、リンクを用いて暴走した覚醒体の少年を抑え込もうとする。"
  },
  AvgDialog_23843_Content_12 = {
    Text = "しかし、あなたはすぐに異変に気づいた。彼の精神は非常に安定しており、一本の蛇のような鎖が彼の精神を引き寄せていた。"
