  AvgDialog_23843_Content_15 = {
    Text = "カエクス、随分時間がかかっているようね。"
  },
  AvgDialog_23843_Content_16 = {
    Text = "ミ、ミリアム様！もう一度チャンスをください、必ずこの二人を片付けます。"
  },
  AvgDialog_23843_Content_17 = {
    Text = "茨の冠を被った女性が彼を一瞥したが、何も答えなかった。\n視線は剣を構えるラモンナに移り、そしてあなたに向けられ、最後にあなたの胸元で微光を放つ銀の鍵に留まった。"
