  AvgDialog_35993_Content_69 = {
    Text = "私たちは皆、あなたをきちんと理解したいの。"
  },
  AvgDialog_35993_Content_7 = {
    Text = "そしてまた、彼女の帰るべき場所でもあった。"
  },
  AvgDialog_35993_Content_8 = {
    Text = "あなたたちの『証拠』とやらは認めないわ。"
  },
  AvgDialog_35993_Content_9 = {
    Text = "この目撃報告と称するものは、犯行が人間のものでないと示すだけ。\n特定の個体を指し示すものではないようね。"
  },
  AvgDialog_35994_Content_1 = {
    Text = "影の童話"
  },
  AvgDialog_35994_Content_10 = {
