  AvgDialog_35994_Content_29 = {Text = "10分後"},
  AvgDialog_35994_Content_3 = {
    Text = "■密境の所有者:メイソン・@2\n■密境潜入者:%player%\n■潜入目的:<Yellow:バーナード医師の死亡事件を調査>"
  },
  AvgDialog_35994_Content_31 = {
    Text = "落ち着いて……「24」さん。"
