  AvgDialog_47169_Content_23 = {
    Text = "どうか、しばしお待ちくださいませ、主よ。"
  },
  AvgDialog_47169_Content_24 = {
    Text = "ミリアム、また寝言を言ってたわよ……大丈夫？"
  },
  AvgDialog_47169_Content_25 = {
    Text = "ええ……大丈夫ですよ、デボラ。"
  },
  AvgDialog_47169_Content_26 = {
    Text = "なんでいつも寝言を言っているのよ。\nもう何回も聞いてるんだからね。"
  },
  AvgDialog_47169_Content_27 = {
    Text = "侍女は歩み寄ると、心配そうに彼女の額に手を添えた。\nミリアムは、ぼうっと彼女を見ている。"
  },
  AvgDialog_47169_Content_28 = {
    Text = "なんでこっち見てるの？"
