  AvgDialog_47169_Content_65 = {
    Text = "本当に？どうしてそんなことがわかるの？"
  },
  AvgDialog_47169_Content_66 = {
    Text = "本当です、デボラ。いずれ、お話ししましょう。\nあなたには、新しき時代の最初の信奉者となっていただきます。\n神の国の、最初の子として。"
  },
  AvgDialog_47169_Content_67 = {
