  AvgDialog_47170_Content_111 = {
    Text = "「『父』？では、『お父様』……王の御言葉は正しかった。わたくしは、運命を背負う者！すべきことと、できることは、数多あります……」"
  },
  AvgDialog_47170_Content_112 = {
