  AvgDialog_51150_Content_16 = {
    Text = "でも、どうしてこんなシディができたんだろう……"
  },
  AvgDialog_51150_Content_17 = {
    Text = "私にもわからない……それに、ここには私の詩と違うところもあるの。あの画家は、本当はとても可愛いおじいさんのはずなんだけど……"
  },
  AvgDialog_51150_Content_18 = {
    Text = "でも、ここをどうにかするには、まずあの詩集を見つける必要があると思うの。"
  },
  AvgDialog_51150_Content_19 = {
    Text = "道は覚えてる？"
  },
  AvgDialog_51150_Content_2 = {
    Text = "あっ、ごめんなさい、守秘者{Male=さん,Female=さん}……少しぼーっとしていました。"
  },
  AvgDialog_51150_Content_20 = {
    Text = "私の詩の中では、三月通りは家のすぐ近くにある。帰り道は、ずっと覚えてるわ。"
  },
  AvgDialog_51150_Content_21 = {
    Text = "彼女はスラム街の方を見て微笑んだ。"
  },
  AvgDialog_51150_Content_22 = {
