  },
  AvgDialog_51998_Content_1 = {
    Text = "ペリシテ人の嘲笑が部屋に響く。ペリシテの隊長は頭を振り、タリスの髪を掴んで、手に持ったナイフを取り出した。"
  },
  AvgDialog_51998_Content_10 = {
    Text = "そうだな、ゴリアテの物は全部捨てないとな。グレンに怪しまれる。"
  },
  AvgDialog_51998_Content_11 = {
    Text = "お前のおかげで思い出したよ。礼に、苦しまずに殺してやる……お？"
  },
  AvgDialog_51998_Content_2 = {
    Text = "彼はミリアムに体を向けた。彼の腰には、小さな像が揺れている。彼女は目を見開いた。"
  },
  AvgDialog_51998_Content_3 = {
    Text = "その像……どこから持ってきたの？"
  },
  AvgDialog_51998_Content_4 = {
