  AvgDialog_52000_Content_6 = {
    Text = "我が主を称えよ……偉大なる王、リモリア……"
  },
  AvgDialog_52000_Content_7 = {
    Text = "祭司と初めて会うたびに、余はこの皮肉を聞くのじゃ。"
  },
  AvgDialog_52000_Content_8 = {
    Text = "リモリアの巨大な王冠は、部屋のどこからともなく現れる暗い輝きを反射し、少年の体に不釣り合いだが、彼の頭にぴったりと収まり、まるで彼の一部のように見える。"
  },
  AvgDialog_52000_Content_9 = {
    Text = "眠い目でミリアムを見つめ、まるで深海のようにかすかに息づいている。幼さの残る顔には、少年らしさは一切見られない。"
  },
  AvgDialog_52001_Content_1 = {
    Text = "でも大丈夫、主はあなたの恐怖を理解してくれるわ。私たちの友情は、こんな侮辱では変わらないから。"
  },
  AvgDialog_52001_Content_10 = {
