  AvgDialog_52001_Content_40 = {
    Text = "ゴリアテはおかしな冗談を聞いたようだ。彼は主座から立ち上がり、刀を手に取った。"
  },
  AvgDialog_52001_Content_41 = {
    Text = "お前たちと協力すれば、アウン族の領地を少し手に入れられる。"
  },
  AvgDialog_52001_Content_42 = {
    Text = "ミリアムと協力すれば、お前たちには想像もできないほどの強大な力を手に入れられる。お前たちの家族をすべて魚人にして、財産をすべて手に入れられるんだ……"
  },
  AvgDialog_52001_Content_43 = {
    Text = "教えてくれ、エドモンドさん。お前が俺だったら、どっちを選ぶ？"
  },
  AvgDialog_52001_Content_44 = {
    Text = "わ、私たちは黙って従ったりしない！"
  },
  AvgDialog_52001_Content_45 = {
    Text = "そうだ！ゴリアテ、エノム族の栄光にかけて、俺たちは……ああああああ！"
  },
  AvgDialog_52001_Content_46 = {
    Text = "巨大な刃が振り下ろされ、若い貴族は真っ二つに切り裂かれ、栄光を証明する力を失った。"
  },
  AvgDialog_52001_Content_47 = {
    Text = "周囲の扉が開き、無数の魚人が波のようにホールに押し寄せた。"
  },
  AvgDialog_52001_Content_48 = {
    Text = "……外の親衛隊はどうした？"
  },
  AvgDialog_52001_Content_49 = {
    Text = "お前らが酒を飲んでる間に、親衛隊は始末した。"
  },
  AvgDialog_52001_Content_5 = {
    Text = "彼女は立ち上がると、優しくデボラに歩み寄った。白い手に握られた奇妙な形の儀式用ナイフが、暗い光を放っている。"
  },
  AvgDialog_52001_Content_50 = {
    Text = "城の外の軍隊とも、もう連絡は取れないぜ。"
  },
  AvgDialog_52001_Content_51 = {
    Text = "鮮血がホールの隅々まで染め上げ、地獄からの交響曲のように、悲鳴が壁にぶつかり、こだまする。"
  },
  AvgDialog_52001_Content_52 = {
    Text = "毒酒を飲まなかった人々は、震え、剣を抜くことも逃げることもできない。"
  },
  AvgDialog_52001_Content_53 = {
    Text = "ゴリアテはホールの血なまぐさい光景を楽しみ、貴族たちの恐怖に満ちた表情を見て、満足そうにため息をつくと、大きな刃を持ち上げた。"
  },
  AvgDialog_52001_Content_54 = {
    Text = "毒酒を飲んで魚人になるか、ここで死ぬか。選べよ。"
  },
  AvgDialog_52001_Content_56 = {
    Text = "いやああああ！！！"
  },
  AvgDialog_52001_Content_57 = {
    Text = "甲高い悲鳴が石板にぶつかり、鈍い響きを返す。"
  },
  AvgDialog_52001_Content_58 = {
    Text = "逃げようともがくが、体はミリアムに支配されていて、動かせない。"
  },
  AvgDialog_52001_Content_59 = {
    Text = "気を失いたいのに、脳は痛みと恐怖を感じ続ける。"
  },
  AvgDialog_52001_Content_6 = {
    Text = "いや！ミリアム！！お願い……お願いだから……こんな残酷なことはやめて……"
  },
  AvgDialog_52001_Content_60 = {
    Text = "「主はすべての信者を守りたもう」って言って。"
  },
  AvgDialog_52001_Content_61 = {
    Text = "デボラの血がミリアムの体に飛び散る。彼女は何年も前、神殿の祭壇で父親を見送ったことを思い出した。"
  },
  AvgDialog_52001_Content_62 = {
    Text = "別れは再会のため……そうですよね、主よ？"
  },
  AvgDialog_52001_Content_63 = {
    Text = "ミリアムはデボラの腹を見つめ、ダガーを動かし、絵の最後の一筆を描いた。"
  },
  AvgDialog_52001_Content_64 = {
    Text = "さあ、デボラ。言って、「求めるものは……」"
  },
  AvgDialog_52001_Content_65 = {
    Text = "ミリアムの手が腹に入り、かき回し、引き裂く。"
  },
  AvgDialog_52001_Content_66 = {
    Text = "デボラはかすれた声で苦しそうに吠え、真紅の目を見開いて自分の腹を見つめた。"
  },
  AvgDialog_52001_Content_67 = {
    Text = "……「願う者には、主が約束を果たす」"
  },
  AvgDialog_52001_Content_68 = {
    Text = "ミリアムは何かを引きちぎった。痛いはずだが、デボラはもう感じなかった。"
  },
  AvgDialog_52001_Content_69 = {
    Text = "彼女の脳はすでに麻痺し、感情も感覚も遠くに離れていた。"
  },
  AvgDialog_52001_Content_7 = {
    Text = "私を見て、デボラ。私を見て……"
  },
  AvgDialog_52001_Content_70 = {
    Text = "彼女はぼんやりと、ミリアムが自分の腹から血まみれの肉塊を抱き出すのを見た。"
  },
  AvgDialog_52001_Content_71 = {
    Text = "サ……サ……"
  },
  AvgDialog_52001_Content_72 = {
    Text = "サナ。ミリアムは彼女から、妹の名前だと聞いていた。"
  },
  AvgDialog_52001_Content_73 = {
    Text = "ノードと相談し、娘にこの名前をつけることにした。しかし、まだミリアムには伝えていない。"
  },
  AvgDialog_52001_Content_74 = {
    Text = "サナと呼んでほしい。デボラはそう呟くが、もう声は出ない。"
  },
  AvgDialog_52001_Content_75 = {
    Text = "「我が主よ、我らの歌声が深海を越え、あなたと共に、無限の安寧と至福の地へ向かいますように」"
  },
  AvgDialog_52001_Content_76 = {
    Text = "ミリアムは愛おしそうに代子に口づけをした。赤子の血が彼女の唇を赤く染める。唇から血が滴り落ち、彼女はデボラの目をそっと覆った。"
  },
  AvgDialog_52001_Content_8 = {
    Text = "あなたが怖がっているのはわかっているわ。多くの信者が、終わりを前にして恐れていたもの。"
  },
  AvgDialog_52001_Content_9 = {
    Text = "でも、心配しないで。あなたは神の国の最も尊い民で、あなたが受けたすべての苦しみは、神の国で報われるわ。"
  },
  AvgDialog_52002_Content_1 = {
    Text = "星辰は正位置に揃い、王の聖胎はすでに聖なる赤子の体内に植え付けられた。まもなく、王は再びこの世に降臨する。"
  },
  AvgDialog_52002_Content_10 = {
    Text = "魚人たちの耳をつんざくような歓声の中、ミリアムは両手を伸ばし、腕の中の赤ん坊を高く掲げた。"
  },
  AvgDialog_52002_Content_11 = {
    Text = "彼女の元々の心臓があった場所で、聖胎は星々の下、清らかな白い光を放っている。"
  },
  AvgDialog_52002_Content_12 = {
    Text = "うわあああああーー"
  },
  AvgDialog_52002_Content_13 = {
    Text = "すべてが静まり返った。血に包まれた赤ん坊が身をよじり、古い廃墟の中で、遅れて初めての泣き声を上げた。"
  },
  AvgDialog_52002_Content_14 = {
    Text = "満天の星が沈黙し、この神託のような泣き声を聞いている。一つの星が落ち、夜空に悲しい跡を残す。"
  },
  AvgDialog_52002_Content_15 = {
    Text = "——星々のもう一つの物語が、始まろうとしている。"
  },
  AvgDialog_52002_Content_2 = {
    Text = "王は善良なる民を守り、神の国へと導いてくださる！"
  },
  AvgDialog_52002_Content_3 = {
    Text = "神の国へ！神の国へ！"
  },
  AvgDialog_52002_Content_4 = {
    Text = "魚人たちは狂ったように歓声を上げ、踊り狂う。ミリアムは人々の中央に立った。星明かりが彼女の血と涙にまみれた顔を照らす。"
  },
  AvgDialog_52002_Content_5 = {
    Text = "王の教えは世界に広まる。祭司様、この教団に名前をつけてください。"
  },
  AvgDialog_52002_Content_6 = {
    Text = "冷たく熱い瞳がゆっくりと動く。ミリアムは彼女の兵士たち、彼女の臣民たちを見渡す。そして祭司として微笑んだ。"
  },
  AvgDialog_52002_Content_7 = {
    Text = "私たちは海を渡り、王の足跡を追う。私たちは海を渡り、王の国を連れてくる……"
  },
  AvgDialog_52002_Content_8 = {
    Text = "人々は私たちを「海踊人」と呼ぶでしょう。"
  },
  AvgDialog_52002_Content_9 = {
    Text = "海踊人！海踊人！！"
  },
  AvgDialog_52003_Content_1 = {
    Text = "王はお前たちに語りかける。祈りなさい。"
  },
  AvgDialog_52003_Content_10 = {
    Text = "周りの人が次々と倒れていく。ミリアムは痛みをこらえ、紙に書かれた祈りの言葉を読み上げた。"
  },
  AvgDialog_52003_Content_11 = {
    Text = "「遥かなる暗き深淵に、古く偉大なる魂が眠る……」"
  },
  AvgDialog_52003_Content_12 = {
    Text = "ミリアムは普通のリモリア語でこれを読んだが、彼女の口から出た言葉は別の言語に変わった。"
  },
  AvgDialog_52003_Content_13 = {
    Text = "同時に、彼女の声が重なり合い、複雑に響き渡る。それは文字と同じように、高次元の構造となり、人間には想像もつかない時空から響いてくるようだった。"
  },
  AvgDialog_52003_Content_14 = {
    Text = "「……神の意志は星々の網のように交差し、神は永遠の虚無の中で汝を夢に誘う……」"
  },
  AvgDialog_52003_Content_15 = {
    Text = "ミリアムは詠唱を続けた。"
  },
  AvgDialog_52003_Content_16 = {
    Text = "いつの間にか、目の前の世界が消えていた。"
  },
  AvgDialog_52003_Content_17 = {
    Text = "彼女は深海にいて、どの方向を見ても、虚無の海しか見えない。"
  },
  AvgDialog_52003_Content_18 = {
    Text = "深海の中では、小さな光が宇宙の星々のように散らばっている。"
  },
  AvgDialog_52003_Content_19 = {
    Text = "ミリアムは自分も星になり、その光がどこかに集まっているのを感じた。彼女はその場所を見つめる。"
  },
  AvgDialog_52003_Content_2 = {
    Text = "老人が部屋を出て行き、中には祭司と数人の衛兵だけが残った。"
  },
  AvgDialog_52003_Content_20 = {
    Text = "無数の光が集まり、人間の体、王座、触手で構成された輪郭を形作る。"
  },
  AvgDialog_52003_Content_21 = {
    Text = "あれは……王様？"
  },
  AvgDialog_52003_Content_22 = {
    Text = "パチン——"
  },
  AvgDialog_52003_Content_23 = {
    Text = "何かの音に驚かされ、彼は玉座から目を覚ました。彼が目を覚ますと、虚無の空間全体が一瞬暗くなった。"
  },
  AvgDialog_52003_Content_24 = {
    Text = "彼の背後に、老人のぼやけた輪郭が現れる。"
  },
  AvgDialog_52003_Content_25 = {
    Text = "彼女の声が聞こえましたか、主よ。"
  },
  AvgDialog_52003_Content_26 = {
    Text = "星々が示す者、それが彼女なのか？"
  },
  AvgDialog_52003_Content_27 = {
    Text = "そうです。すでに確認済みです。星々が示す通り、彼女は……リモリアの未来です。"
  },
  AvgDialog_52003_Content_28 = {
    Text = "だが、お前はそう思っていない。"
  },
  AvgDialog_52003_Content_29 = {
    Text = "才能はありますが、雑念もあります。彼女はあなた様の助けにはなりません。"
  },
  AvgDialog_52003_Content_3 = {
    Text = "礼拝室の光が暗くなり、前方の像が神秘的な暗い光を放つ。"
  },
  AvgDialog_52003_Content_30 = {
    Text = "彼女は祈りを信じておらず、あなた様も、リモリアの未来も信じていません。彼女が信じているのは、家族だけです。"
  },
  AvgDialog_52003_Content_31 = {
    Text = "ミリアムは現実に生きる人間です。そういう人間は、リモリアの運命を背負うことはできません。"
  },
  AvgDialog_52003_Content_32 = {
    Text = "現実に生きることこそ、余の望みだ。"
  },
  AvgDialog_52003_Content_33 = {
    Text = "素晴らしい願いです、主よ。しかしリモリアに生まれた以上、私たちには果たすべき責務があります。"
  },
  AvgDialog_52003_Content_34 = {
    Text = "私たちに選択肢はありません。彼女も、私も、あなた様も、皆同じです。"
  },
  AvgDialog_52003_Content_35 = {
    Text = "……つまらぬ。余は休むぞ。"
  },
  AvgDialog_52003_Content_36 = {
    Text = "彼は手を振った。老人は彼に頭を下げ、無辺の虚無へと消えていった。"
  },
  AvgDialog_52003_Content_37 = {
    Text = "眠りにつく前に、彼は自分に光を捧げる人々を見た。誰にも聞こえないため息が、無限の虚空に消えていった。"
  },
  AvgDialog_52003_Content_38 = {
    Text = "ああっ！"
  },
  AvgDialog_52003_Content_39 = {
    Text = "心臓が落ちるような感覚の後、強烈な刺痛が走る。"
  },
  AvgDialog_52003_Content_4 = {
    Text = "ミリアムは祈祷書を手に取った。"
  },
  AvgDialog_52003_Content_40 = {
    Text = "痛みは長くは続かなかった。ミリアムは虚無の空間から抜け出し、周囲を見渡した。"
  },
  AvgDialog_52003_Content_41 = {
    Text = "祈りの言葉を読めない人々はすでに退出させられ、残った人々の半分は苦しそうに地面に倒れ、残りは幸せそうな笑顔で目を閉じ祈っていた。"
  },
  AvgDialog_52003_Content_42 = {
    Text = "デボラは隣で微笑みながらゆっくりと目を開け、ミリアムの様子を見て心配そうな表情を浮かべた。"
  },
  AvgDialog_52003_Content_5 = {
    Text = "ああ……"
  },
  AvgDialog_52003_Content_6 = {
    Text = "紙に書かれていたのは、リモリアの共通語ではなく、現実空間よりも多くの次元を持つ複雑な象形文字だった。"
  },
  AvgDialog_52003_Content_7 = {
    Text = "その文字は古代、あるいは別の世界から来たもので、ミリアムは見たことがなかった。しかし、その意味は自動的に彼女の脳に入ってきた。"
  },
  AvgDialog_52003_Content_8 = {
    Text = "文字一つ一つが膨大な情報量を含んでおり、無数の経文がミリアムの脳に流れ込み、彼女の脆弱な頭を圧迫した。"
  },
  AvgDialog_52003_Content_9 = {
    Text = "<Shake:あた……頭が痛い……>"
  },
  AvgDialog_52004_Content_1 = {
    Text = "王を信じれば、王は応えてくれる……"
  },
  AvgDialog_52004_Content_10 = {
    Text = "あなたの慧眼が災厄を見抜き、\nあなたの知恵が民を導きますように。"
  },
  AvgDialog_52004_Content_11 = {
    Text = "「あなたの慧眼が災厄を見抜き、\nあなたの知恵が民を導きますように！」"
  },
  AvgDialog_52004_Content_12 = {
    Text = "嵐は静まり、波は止み、\n地震は収まり、大地は安らぐ。"
  },
  AvgDialog_52004_Content_13 = {
    Text = "あなたの安らかな夢の中で、災厄は虚無と化す。\nあなたの加護の中で、私たちは神の国を迎える。"
  },
  AvgDialog_52004_Content_14 = {
    Text = "「あなたの安らかな夢の中で、災厄は虚無と化す！」"
  },
  AvgDialog_52004_Content_15 = {
    Text = "「あなたの庇護の下で、\n我らは神の国を迎える……」"
  },
  AvgDialog_52004_Content_16 = {Text = "轟……"},
  AvgDialog_52004_Content_17 = {
    Text = "轟音の響きとともに、神殿の下から巨大な触手が現れた。"
  },
  AvgDialog_52004_Content_18 = {
    Text = "王だ！王の神跡が現れた！！！"
  },
  AvgDialog_52004_Content_19 = {
    Text = "信者たちは両手を広げ、狂ったように歓声を上げる。"
  },
  AvgDialog_52004_Content_2 = {
    Text = "だから教えて、あなたは王を信じる？あなたのすべてを、王に捧げる？"
  },
  AvgDialog_52004_Content_20 = {
    Text = "触手が風雨の中で揺れ、リモリアの人々は疑わなかった。偉大な神々は、あらゆる災厄に打ち勝つ力を持っていると。"
  },
  AvgDialog_52004_Content_21 = {
    Text = "我が主、トゥルー！"
  },
  AvgDialog_52004_Content_22 = {
    Text = "我が主、トゥルー！！トゥルー！！！"
  },
  AvgDialog_52004_Content_23 = {
    Text = "彼女は振り返り、神殿の中を見て、跪いた。"
  },
  AvgDialog_52004_Content_24 = {
    Text = "誰にも見えないその目には、祭司としての期待も威厳もなく、ただ迷いが残っていた。"
  },
  AvgDialog_52004_Content_25 = {
    Text = "信者の呼びかけをお聞きください。神の国を、私たちに。"
  },
  AvgDialog_52004_Content_26 = {
    Text = "神の国を、私たちに！"
  },
  AvgDialog_52004_Content_27 = {
    Text = "我が主！神の国を！ははは……神の国が降臨する！"
  },
  AvgDialog_52004_Content_28 = {
    Text = "狂気の叫びとともに、触手が舞い始める。深海の静けさが触手からリモリアの人々の感覚に伝わってくる。"
  },
  AvgDialog_52004_Content_29 = {
    Text = "ドーン——"
  },
  AvgDialog_52004_Content_3 = {
    Text = "王を信じています、祭司様！すべてを王に捧げます！"
  },
  AvgDialog_52004_Content_30 = {
    Text = "雷鳴とともに歓声が止む。稲妻が空を照らし、リモリアの孤独な土地を照らし出す。"
  },
  AvgDialog_52004_Content_31 = {
    Text = "狂喜の中、信者たちは動きを止めた。王への賛美と信仰の中で、未来への無限の想像と希望の中で。"
  },
  AvgDialog_52004_Content_32 = {
    Text = "暴風雨の中、リモリアの民は深い眠りについた。"
  },
  AvgDialog_52004_Content_4 = {
    Text = "私は王の最も忠実な信者です！"
  },
  AvgDialog_52004_Content_5 = {
    Text = "捧げます！祭司様、喜んで捧げます！"
  },
  AvgDialog_52004_Content_6 = {
    Text = "では今、私と一緒に王の名前を唱えて——"
  },
  AvgDialog_52004_Content_7 = {
    Text = "彼女は広場の全員を見渡した。"
  },
  AvgDialog_52004_Content_8 = {
    Text = "暴風雨の中、全員が跪き、両手を広げ、神殿の玉座の方を見つめた。"
  },
  AvgDialog_52004_Content_9 = {
    Text = "星々の輝く空の下、深海の孤島の上で、主に祈りを捧げます。"
  },
  AvgDialog_52005_Content_1 = {
    Text = "そうよ、お父さん……神の国でまた会えるのよね！家族みんなで、神の国で暮らすのよね……"
  },
  AvgDialog_52005_Content_10 = {
    Text = "神の国はもうすぐよ。そしたら家族みんなで、また一緒に……"
  },
  AvgDialog_52005_Content_11 = {
    Text = "ブスッ——"
  },
  AvgDialog_52005_Content_12 = {
    Text = "ダガーがイノスの胸に深々と突き刺さり、彼は苦しそうにうめいた。鮮血が飛び散り、ミリアムの右半分の顔を赤く染める。"
