  AvgDialog_58294_Content_83 = {
    Text = "どうしたの、ライカー？\nすごく顔色が悪いよ。"
  },
  AvgDialog_58294_Content_84 = {
    Text = "なんでもない。\n少し独りになりたいんだ。すぐ戻るよ。"
  },
  AvgDialog_58294_Content_85 = {
    Text = "探偵は穏やかな顔で、あなたたちに親しげな微笑みを向けた。"
  },
  AvgDialog_58294_Content_86 = {
    Text = "ライカーはほとんど振り返ることなく、去っていった。"
  },
  AvgDialog_58294_Content_87 = {
    Text = "ライカー……？"
  },
  AvgDialog_58294_Content_9 = {
    Text = "あなたは探偵の足を、思いきり踏みつけた。しかし負けず嫌いな探偵は、あなたの激しい合図を、まるで意に介さない。"
  },
  AvgDialog_58326_Content_1 = {
    Text = "逆向の推理"
  },
  AvgDialog_58326_Content_10 = {
    Text = "イエスなら一回、ノーなら二回叩いてくれ。\nできるかい？"
  },
  AvgDialog_58326_Content_11 = {
    Text = "厚い黒檀の板越しに聞こえるライカーの声は、どこか不確かで、それでいて柔らかな優しさが含まれていた。"
  },
  AvgDialog_58326_Content_12 = {
    Text = "あなたは一度、軽くノックした。"
  },
  AvgDialog_58326_Content_13 = {
    Text = "よかった！\nなに、簡単さ。質問は、たったの三つ。"
  },
  AvgDialog_58326_Content_14 = {
    Text = "最初の質問だよ。\n君は、誰かに閉じ込められているのか？"
  },
  AvgDialog_58326_Content_15 = {
    Text = "<Yellow:コン。>"
  },
  AvgDialog_58326_Content_16 = {
    Text = "二つ目の質問。\n君は、「私たち」——あの男の密境に入ったメンバーの仲間？"
  },
  AvgDialog_58326_Content_17 = {
    Text = "<Yellow:コン。>"
  },
  AvgDialog_58326_Content_18 = {
    Text = "よし、私の直感は間違っていない。\nそれじゃ、三つ目の質問だ……"
  },
  AvgDialog_58326_Content_19 = {
    Text = "君は、%player%なのか？"
  },
  AvgDialog_58326_Content_2 = {
    Text = "ノックの音は、なおも続いている。"
  },
  AvgDialog_58326_Content_20 = {
    Text = "あなたは棺を強く、一度だけ叩いた。\nすると、すぐに軽い笑い声が聞こえてきた。"
  },
  AvgDialog_58326_Content_21 = {
    Text = "やっぱり君か。怖がらなくていい。私がすべての謎を解いて、君を必ず助け出す。だからここで、大人しくしていてほしい。いいね？"
  },
  AvgDialog_58326_Content_22 = {
    Text = "<Yellow:コン。>"
  },
  AvgDialog_58326_Content_23 = {
    Text = "いいね、友よ。また会おう。"
  },
  AvgDialog_58326_Content_24 = {
    Text = "耳元に衣擦れの音が響き、足音は次第に遠ざかっていった。"
  },
  AvgDialog_58326_Content_25 = {
    Text = "あなたは大きく息を吐き、目を閉じた。\nしかし、いくらも経たないうちに、足音が戻ってきた。"
  },
  AvgDialog_58326_Content_26 = {
    Text = "すまない、一番重要な問いを忘れていたよ。\nこれからの私の行動にとって、決定的に重要な問いだ。"
  },
  AvgDialog_58326_Content_27 = {
    Text = "あなたは静かに、その『重要な問い』を待つ。"
  },
  AvgDialog_58326_Content_28 = {
    Text = "君は、私を信じているか？"
  },
  AvgDialog_58326_Content_29 = {
    Text = "<Gray:なにいってるんだ、この人は……>"
  },
  AvgDialog_58326_Content_3 = {
    Text = "やあ、棺桶の中の君、元気かい？"
  },
  AvgDialog_58326_Content_30 = {
    Text = "あなたは微笑んで手を伸ばし、滑らかな棺の内壁に触れた。"
  },
  AvgDialog_58326_Content_31 = {
    Text = "——コン。"
  },
  AvgDialog_58326_Content_32 = {
    Text = "私は君を、信じている。"
  },
  AvgDialog_58326_Content_33 = {
    Text = "なるほど。あなたの直感はいつも鋭い。"
  },
  AvgDialog_58326_Content_34 = {
    Text = "ですが、残念なことに……{Male=彼,Female=彼女}は<Yellow:あれ>の意識に囚われました。あなたが最後の真実を解き明かしても、もう手遅れですよ。"
  },
  AvgDialog_58326_Content_35 = {
    Text = "現実は、私が精魂込めて選び抜いた器の意識の中に、{Male=彼,Female=彼女}が永遠に囚われ続ける、ということです。"
  },
  AvgDialog_58326_Content_36 = {Text = "！？"},
  AvgDialog_58326_Content_37 = {
    Text = "君は言った。すべての真相を解き明かせば……"
  },
  AvgDialog_58326_Content_38 = {
    Text = "Nの顔からゆるやかに流れだす黒い霧は、心地よさそうにその身をくねらせた。さながら、極上の珍味を味わっているかのように。"
  },
  AvgDialog_58326_Content_39 = {
    Text = "ふふ……あなたのそんな表情を見るのは初めてですね。\nですが、残念ながら、怒りでは何ひとつ解決できません。"
  },
  AvgDialog_58326_Content_4 = {
    Text = "聞こえてきた軽やかで楽しげな声は、まるで不思議な魔法のように、たちまちあなたの涙を止めた。"
  },
  AvgDialog_58326_Content_40 = {
    Text = "私は密境を解放すると約束しただけです。\n全員が無事であるとは、一言も言っていませんよ。"
  },
  AvgDialog_58326_Content_41 = {
    Text = "さあ、お仲間にお別れを。\n私の探偵さん。"
  },
  AvgDialog_58326_Content_42 = {
    Text = "Nは軽く指を上げた。\nしかし、その次の瞬間——"
  },
  AvgDialog_58326_Content_43 = {
    Text = "<Red:悪夢はすでに終わった、目を開けよ。>"
  },
  AvgDialog_58326_Content_44 = {
    Text = "ゴゴゴゴ……"
  },
  AvgDialog_58326_Content_45 = {
    Text = "突然足元の床が裂けた。\n底知れぬ深淵から漆黒の大蛇が飛び出し、瞬く間にNの身体を貫く。"
  },
  AvgDialog_58326_Content_47 = {
    Text = "説明しておきましょう。この身体の八割は、霧で構成されています。残りの二割も、やはり霧。この程度の小細工は無駄——"
  },
  AvgDialog_58326_Content_48 = {
    Text = "不意に、銀色の閃光が走った。\nまるで、演目の幕開けを告げる照明のように。"
  },
  AvgDialog_58326_Content_49 = {
    Text = "縮れ毛の学生が、片手で凝り固まった肩を揉み、もう一方の手で銀の鍵を握りしめ、暗闇の最奥から歩み出る。"
  },
  AvgDialog_58326_Content_5 = {
    Text = "悪かったね。\nさっきは少々言葉が過ぎた。"
  },
  AvgDialog_58326_Content_50 = {
    Text = "ふう……なんとか間に合ったかな。"
  },
  AvgDialog_58326_Content_51 = {
    Text = "さすが、私の眼鏡にかなった守秘者だ！\n君がそう簡単にやられるようなタマじゃないと、わかっていたよ。"
  },
  AvgDialog_58326_Content_52 = {
    Text = "ふふ、当然。"
  },
  AvgDialog_58326_Content_53 = {
    Text = "これも、棺の中で出会った、新しい仲間たちのおかげだよ。"
  },
  AvgDialog_58326_Content_54 = {
    Text = "シュー……"
  },
  AvgDialog_58326_Content_57 = {
    Text = "久しぶりですね、アポフィス。"
  },
  AvgDialog_58326_Content_6 = {
    Text = "だが、今は疑問が山ほどあってね。\n君に詳しく聞きたいところなんだか……話すのはしんどくないか？"
  },
  AvgDialog_58326_Content_7 = {
    Text = "<Change>うん、大丈夫！！"
  },
  AvgDialog_58326_Content_8 = {
    Text = "あなたはありったけの力を振り絞って声を発したが、言葉は口に出るや否や、寝言のように曖昧で不明瞭な呟きへと変わってしまった。"
  },
  AvgDialog_58326_Content_9 = {
    Text = "こいつは少々厄介だな……そうだ。手はまだ動かせるかい？"
  },
  AvgDialog_58327_Content_1 = {
    Text = "幸運を！"
  },
  AvgDialog_58327_Content_10 = {
    Text = "デクスターはとぼけた様子で両手を広げてみせた。"
  },
  AvgDialog_58327_Content_11 = {
    Text = "私も知りたいね。\n取り調べを始める前に、現実と密境の違いをはっきりさせてほしい。"
  },
  AvgDialog_58327_Content_12 = {
    Text = "現実の世界では、私の屋敷で事件なんて一度も起きていない。\n違うかね？"
  },
  AvgDialog_58327_Content_14 = {
    Text = "誰かライカーを見たかしら？\nさっき目を覚ましたエルサが、ライカーにサインをねだってるわ。"
  },
  AvgDialog_58327_Content_15 = {
    Text = "ライカーにファンがいるなんて……驚きね。"
  },
  AvgDialog_58327_Content_16 = {
    Text = "彼は、彼女を怪物の手から救い出した恩人だから。\nそうね、強いて言うなら……"
  },
  AvgDialog_58327_Content_17 = {
    Text = "エルサがミサゴで学ぶことを選んだのも、いつかライカーのようになりたいと思ったから——"
  },
  AvgDialog_58327_Content_18 = {
    Text = "ギャンブラーになりたいのか？"
  },
  AvgDialog_58327_Content_19 = {
    Text = "人助けしたいのよ。"
  },
  AvgDialog_58327_Content_2 = {
    Text = "ミサゴ大学キャンパス\n一週間後"
  },
  AvgDialog_58327_Content_20 = {
    Text = "ライカーは、普段学校にいるのを好まないから。それから%player%は……大事なな用事があるからって、朝早く出ていったわ。"
  },
  AvgDialog_58327_Content_21 = {
    Text = "それに……なんだかおかしいような気がするの。本当にＮは、ただライカーをからかうためだけに、あんな密境を仕掛けたの？"
  },
  AvgDialog_58327_Content_22 = {
    Text = "そうかもしれないし、そうじゃないかもしれない。\nこの問題は、粒子と波動の二重性くらい難しいの。\nだから、もっと現実的なことを考えるべきだわ。"
  },
  AvgDialog_58327_Content_23 = {
    Text = "例えば、ハンナの風をどうしたらいいか、とか。"
  },
  AvgDialog_58327_Content_24 = {
    Text = "果てしない漆黒の洞窟の中、暗夜に揺らめく鬼火のように、無数の目がゆっくりと開閉している。"
  },
  AvgDialog_58327_Content_25 = {
    Text = "冷たい風が吹き抜ける。洞窟の中央では黒い霧が静かに蠢いていた。やがてそれは、かろうじて人影に見える、ぼんやりとした形を成す。"
  },
  AvgDialog_58327_Content_26 = {
    Text = "<Change>うう……ご主人様……痛い……"
  },
  AvgDialog_58327_Content_27 = {
    Text = "久しぶりだね、憎らしくも愛しい子供たち。\n前にここへ来たのは、もう何百年も前のことだ。"
  },
  AvgDialog_58327_Content_28 = {
    Text = "見せてもらおうか、お前たちが大人になったかどうか……ああ、ごめん。忘れていた。お前たちには、もう目しか残ってなかったね。"
  },
  AvgDialog_58327_Content_29 = {
    Text = "<Change>ご主人さま……愛して……"
  },
  AvgDialog_58327_Content_30 = {
    Text = "さて、旧友を温めるのはまた今度にしよう。\n今回は、一つ面白いことを確かめられたんだ。"
  },
  AvgDialog_58327_Content_31 = {
    Text = "あの守秘者が、まさか本当にカナックの意識と共鳴するなんてね……実に興味深い。"
  },
  AvgDialog_58327_Content_32 = {
    Text = "<Change>えへへ……ららら……"
  },
  AvgDialog_58327_Content_33 = {
    Text = "うるさいな……ちょうど私の幻影が傷ついてしまって、ささやかな癒しが必要なのに。"
  },
  AvgDialog_58327_Content_34 = {Text = "黙れ。"},
  AvgDialog_58327_Content_36 = {
    Text = "すさまじい嗚咽とともに、すべての目が握りつぶされた。\nぽたりぽたりと、血が地面に滴り落ちる。"
  },
  AvgDialog_58327_Content_37 = {
    Text = "黒い霧は瞬く間に膨れ上がり、空気中に漂う血の霧を、貪るように呑み込んでいく。やがて朧げだった人影は、ついに実体を得た。"
  },
  AvgDialog_58327_Content_38 = {
    Text = "なんてひどい味だ……"
  },
  AvgDialog_58327_Content_39 = {
    Text = "ハイゲート墓地\nロンディニウム東区、ケント郡"
  },
  AvgDialog_58327_Content_4 = {
    Text = "少しは良くなった？\nシルヴィアさんから、食欲があまりないって聞いたけど。"
  },
  AvgDialog_58327_Content_40 = {
    Text = "ほら、私が最初に刑務所送りにした不運なヤツは、ここに埋められているんだ。"
  },
  AvgDialog_58327_Content_41 = {
    Text = "あなたたちは、片隅にひっそり立っている墓碑の前で、足を止めた。"
  },
  AvgDialog_58327_Content_42 = {
    Text = "密境での推理結果について、君は人違いをした可能性が高いと思う。二本の絞め痕と失われた靴について、君はまだ説明できていない。"
  },
  AvgDialog_58327_Content_43 = {
    Text = "私はそうは思わないな。ロープに犯人の血がついたから、慌てて取り替えられたのではないと、どうして言える？"
  },
  AvgDialog_58327_Content_44 = {
    Text = "消えた靴については——奇妙な話ではあるがね。だが、真夜中に自分の家で靴を履いていないなんて、別におかしなことじゃないだろう？"
  },
  AvgDialog_58327_Content_45 = {
    Text = "まして1階の窓から人を吊り上げるには、どれほどの力と正確さが要ると思う？あの夜は、死者を除けば女性や子供ばかりだったんだぞ。"
  },
  AvgDialog_58327_Content_46 = {
    Text = "うん、その理由なら納得するよ。"
  },
  AvgDialog_58327_Content_47 = {
    Text = "だから、ね——"
  },
  AvgDialog_58327_Content_48 = {
    Text = "ライカーはにっこり笑って、あなたの小さな頭をぽんと叩いた。"
  },
  AvgDialog_58327_Content_49 = {
    Text = "現実の世界は推理小説じゃないのさ、守秘者よ。\n誰もそんな周りくどいやり方で、人を殺したりはしないよ。"
  },
  AvgDialog_58327_Content_5 = {
    Text = "絞殺されて生き返るなんて、気持ちのいいものではないな。\n今でも喉に石が詰まっているような気がするよ。"
  },
  AvgDialog_58327_Content_50 = {
    Text = "ふっ。推理小説じゃないって？\n君の運がよかったってこと？"
  },
  AvgDialog_58327_Content_51 = {
    Text = "そうかもね。君はどう思う？どうして私は、偶然手がかりを見つけられたんだ？まるで手がかりに足が生えていたみたいじゃないか。"
  },
  AvgDialog_58327_Content_52 = {
    Text = "人は数学者が問題を解くのを見ると、その天才ぶりに驚愕する。\nだが、天才なんてものは、普通の人より少し先んじているだけさ。"
  },
  AvgDialog_58327_Content_53 = {
    Text = "ライカーは高らかに笑いながら、見えない遠くへ向かって勝利のポーズを決めた。"
  },
  AvgDialog_58327_Content_54 = {
    Text = "君も、私と同じだろう？"
  },
  AvgDialog_58327_Content_55 = {
    Text = "探偵の幼稚な仕草に、誰も応えなかった。一陣の風が通り抜け、木の葉が優しくざわめく。空は次第に暗さを増していった。"
  },
  AvgDialog_58327_Content_56 = {
    Text = "つまらないな。\nどうやらもうすぐ、雨が降りそうだ。行こう。"
  },
  AvgDialog_58327_Content_57 = {
    Text = "あなたとライカーは、縦に並んで墓地を歩いた。\n足元の落ち葉が、かすかな音を立てる。どちらも口を開かなかった。"
  },
  AvgDialog_58327_Content_58 = {
    Text = "そういえば……私たちも、これだけ一緒にやってきたんだ。\n物語の定番の展開で、そろそろ君が過去を語ってくれてもいいよね。"
  },
  AvgDialog_58327_Content_59 = {
    Text = "例えば、君の故郷はどこかとか。どうして足を踏み外して、ギャンブルにのめり込んでしまったのか、とか……"
  },
  AvgDialog_58327_Content_6 = {
