  AvgDialog_58328_Content_10 = {
    Text = "あの人は東区じゃ有名な「幸運の探偵」だからね。"
  },
  AvgDialog_58328_Content_11 = {
    Text = "ライカーさんが関わった事件は、まるで足でも生えたみたいに、次々と手がかりが現れるんだ。犯人は三日も隠れていられないよ！"
  },
  AvgDialog_58328_Content_12 = {
    Text = "ライカーさんと一緒にいたら、一日で10スタールも拾ったって人までいるくらいだよ。とにかく、みんなにとって幸運の神様なんだ！"
