  AvgDialog_60209_Content_4 = {
    Text = "アリステアは長く黙したまま、窓の外に広がる空虚な昏き海を見つめていた。さまざまな思考が彼の中でせめぎ合っているのだろう。"
  },
  AvgDialog_60209_Content_40 = {
    Text = "%player%、備えを万全に。\n間もなく、重大な出来事が起こるでしょう。"
