  AvgDialog_66599_Content_2 = {
    Text = "胸の震動。シルバーキーが何かに呼ばれ、あなたの前に漂う。"
  },
  AvgDialog_66599_Content_20 = {
    Text = "至高の意志をどうやって倒せばいいのか、教えて下さい。どうしたら彼らを守れるのか"
  },
  AvgDialog_66599_Content_21 = {
    Text = "キヘマー・ダアート。その名がはっきりと響いた。"
  },
  AvgDialog_66599_Content_22 = {
    Text = "泡が一つ漂ってくる。あなたは指を伸ばし、それに触れる。"
