  AvgDialog_66599_Content_23 = {
    Text = "パッ——"
  },
  AvgDialog_66599_Content_24 = {
    Text = "「泡が無数の光点に砕ける。光点が紗のように包む」"
  },
  AvgDialog_66599_Content_25 = {
