  },
  AvgDialog_66599_Content_28 = {
    Text = "ダメ……生命、文明、感情……私たちの世界はこんなに簡単に消し去ることはできない！"
  },
  AvgDialog_66599_Content_29 = {
    Text = "私を見て。聞いて。目のない瞳の破片。目のない瞳の意識。目のない瞳の暗い面"
  },
  AvgDialog_66599_Content_3 = {
