  AvgDialog_78941_Content_44 = {
    Text = "突如として雷鳴が轟き、ノーチラス号は再び激しく揺れ始める。\nまるで何者かに掴まれ、弄ばれているかのようだった。"
  },
  AvgDialog_78941_Content_45 = {
    Text = "なんてことだ、あ、あれは一体……"
  },
  AvgDialog_78941_Content_46 = {
    Text = "人々は悲鳴を上げるが、荒れ狂う波と船体の軋む音とは比べ物にならなかった。"
  },
  AvgDialog_78941_Content_47 = {
    Text = "海面から、巨大な腕のような、形容しがたい形の触手が現れた。\nそれは船首に絡みつき、傍若無人に破壊を始める。"
  },
  AvgDialog_78941_Content_48 = {
