  AvgDialog_81527_Content_68 = {
    Text = "どうしてサボテンが見つからないのかって？人間の感覚だけで探すのは難しいけれど、動物たちの足跡を辿れば、簡単に見つけられるわ。"
  },
  AvgDialog_81527_Content_69 = {
