  AvgDialog_81527_Content_81 = {
    Text = "そう……でも、そんなに心配しなくてもいいと思うわ。"
  },
  AvgDialog_81527_Content_82 = {
    Text = "タイスは気楽そうにサソリを回し続ける。\nカストルはその黒くおぞましい生き物を見つめていたが、ふと香ばしい匂いが漂ってくるのを感じた。"
  },
  AvgDialog_81527_Content_83 = {Text = "なぜ？"},
  AvgDialog_81527_Content_84 = {
    Text = "アランでは、繁殖を中心とした種族文化が盛んなのよ。私たちは、同じ日に生まれた子どもたちは共通の運命を共有していると信じているの。ましてや互いに寄り添って生まれた双子なら……その運命は一生絡み合うと定められている。"
  },
  AvgDialog_81527_Content_85 = {
